window.BB_INDEX=[{"t": "s", "c": 1, "ch": "Human Cognition & Behavior", "id": "1.1", "title": "Attention & Focus", "body": "What users can attend to at any moment.", "url": "1-1-attention-and-focus.html"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "11/01", "title": "Require attention to be earned.", "body": "Do not introduce signals that do not justify their cognitive cost.", "url": "1-1-attention-and-focus.html#11-01", "sub": "1.1 Attention & Focus"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "11/02", "title": "Prioritize relevance over visibility.", "body": "Emphasize what matters now and deliberately de-emphasize everything else.", "url": "1-1-attention-and-focus.html#11-02", "sub": "1.1 Attention & Focus"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "11/03", "title": "Interrupt only when necessary.", "body": "Break focus solely when inaction would cause greater harm than interruption.", "url": "1-1-attention-and-focus.html#11-03", "sub": "1.1 Attention & Focus"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "11/04", "title": "Guide attention toward action.", "body": "Use emphasis to support task progress, not novelty or decoration.", "url": "1-1-attention-and-focus.html#11-04", "sub": "1.1 Attention & Focus"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "11/05", "title": "Enforce foreground–background discipline.", "body": "Keep background activity unobtrusive unless user outcomes depend on awareness.", "url": "1-1-attention-and-focus.html#11-05", "sub": "1.1 Attention & Focus"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "11/06", "title": "Preserve task continuity.", "body": "Ensure users can always resume without questioning their previous state.", "url": "1-1-attention-and-focus.html#11-06", "sub": "1.1 Attention & Focus"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "11/07", "title": "Design explicitly for re-entry.", "body": "Assume interruption and make recovery fast, clear, and predictable.", "url": "1-1-attention-and-focus.html#11-07", "sub": "1.1 Attention & Focus"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "11/08", "title": "Use motion to clarify change.", "body": "Apply animated transitions only to explain state transitions, not to attract attention.", "url": "1-1-attention-and-focus.html#11-08", "sub": "1.1 Attention & Focus"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "11/09", "title": "Treat calm as a functional requirement.", "body": "Use silence, restraint, and visual economy as active design tools.", "url": "1-1-attention-and-focus.html#11-09", "sub": "1.1 Attention & Focus"}, {"t": "s", "c": 1, "ch": "Human Cognition & Behavior", "id": "1.2", "title": "Cognitive Load", "body": "How much mental effort interaction demands.", "url": "1-2-cognitive-load.html"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "12/01", "title": "Design for finite cognitive capacity.", "body": "Do not demand sustained attention, memory, or decision-making beyond what is strictly necessary for the task.", "url": "1-2-cognitive-load.html#12-01", "sub": "1.2 Cognitive Load"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "12/02", "title": "Assume users are already cognitively occupied.", "body": "Design with cognitive courtesy as a baseline responsibility.", "url": "1-2-cognitive-load.html#12-02", "sub": "1.2 Cognitive Load"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "12/03", "title": "Minimize interface thinking.", "body": "Ensure users think about their work and goals, not about how the system operates.", "url": "1-2-cognitive-load.html#12-03", "sub": "1.2 Cognitive Load"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "12/04", "title": "Require the system to remember on users’ behalf.", "body": "Do not make users recall what the system can present for recognition.", "url": "1-2-cognitive-load.html#12-04", "sub": "1.2 Cognitive Load"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "12/05", "title": "Make state visible to reduce mental bookkeeping.", "body": "Do not hide information to avoid errors or uncertainty.", "url": "1-2-cognitive-load.html#12-05", "sub": "1.2 Cognitive Load"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "12/06", "title": "Eliminate interpretive burden.", "body": "Do not require guessing scope, state, or consequences in order to proceed correctly.", "url": "1-2-cognitive-load.html#12-06", "sub": "1.2 Cognitive Load"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "12/07", "title": "Use consistency to convert reasoning into habit.", "body": "Make system behavior predictable to replace conscious reasoning with habitual response.", "url": "1-2-cognitive-load.html#12-07", "sub": "1.2 Cognitive Load"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "12/08", "title": "Reduce decision density.", "body": "Keep users from making frequent or unnecessary micro-decisions within a single task flow.", "url": "1-2-cognitive-load.html#12-08", "sub": "1.2 Cognitive Load"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "12/09", "title": "Ensure automation removes work rather than adds supervision.", "body": "Do not introduce automation that requires constant monitoring, correction, or verification.", "url": "1-2-cognitive-load.html#12-09", "sub": "1.2 Cognitive Load"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "12/10", "title": "Design for sustained use.", "body": "Treat small inefficiencies as compounding costs that accumulate into fatigue over time.", "url": "1-2-cognitive-load.html#12-10", "sub": "1.2 Cognitive Load"}, {"t": "s", "c": 1, "ch": "Human Cognition & Behavior", "id": "1.3", "title": "Recognition", "body": "Whether users can easily recognize instead of remember.", "url": "1-3-recognition.html"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "13/01", "title": "Favor recognition over recall.", "body": "Design interfaces so users can act by seeing and choosing rather than by remembering and reconstructing.", "url": "1-3-recognition.html#13-01", "sub": "1.3 Recognition"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "13/02", "title": "Substitute memory with perception wherever possible.", "body": "Present information whenever possible so users do not have to remember it.", "url": "1-3-recognition.html#13-02", "sub": "1.3 Recognition"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "13/03", "title": "Make action-relevant state continuously visible.", "body": "Do not hide state that influences outcomes or availability.", "url": "1-3-recognition.html#13-03", "sub": "1.3 Recognition"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "13/04", "title": "Expose choices at the point of decision.", "body": "Ensure users can see available options when they need to choose, not before or after.", "url": "1-3-recognition.html#13-04", "sub": "1.3 Recognition"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "13/05", "title": "Maintain spatial stability to reinforce recognition.", "body": "Keep controls and feedback in consistent locations so recognition replaces recall over time.", "url": "1-3-recognition.html#13-05", "sub": "1.3 Recognition"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "13/06", "title": "Make meaningful differences perceptible.", "body": "Do not require users to remember rules or exceptions to distinguish safe actions from risky ones.", "url": "1-3-recognition.html#13-06", "sub": "1.3 Recognition"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "13/07", "title": "Support error recovery through recognition.", "body": "Provide visible history and undo so users can recover without relying on memory.", "url": "1-3-recognition.html#13-07", "sub": "1.3 Recognition"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "13/08", "title": "Design for infrequent and returning use through recognition.", "body": "Ensure users can reorient and resume work without relying on memory or relearning prior knowledge.", "url": "1-3-recognition.html#13-08", "sub": "1.3 Recognition"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "13/09", "title": "Do not sacrifice recognition for minimalism.", "body": "Visual restraint must not remove cues users rely on to recognize actions, state, or structure.", "url": "1-3-recognition.html#13-09", "sub": "1.3 Recognition"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "13/10", "title": "Design recognition-based interfaces to scale.", "body": "Prefer recognition over training so usability does not degrade as systems grow in scope or complexity.", "url": "1-3-recognition.html#13-10", "sub": "1.3 Recognition"}, {"t": "s", "c": 1, "ch": "Human Cognition & Behavior", "id": "1.4", "title": "Mental Models", "body": "How users believe a system works.", "url": "1-4-mental-models.html"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "14/01", "title": "Design explicitly for the mental model users will form.", "body": "Do not allow users to infer core system behavior accidentally or inconsistently.", "url": "1-4-mental-models.html#14-01", "sub": "1.4 Mental Models"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "14/02", "title": "Design consistent system behavior to teach the correct mental model.", "body": "Do not rely on documentation to teach users the correct mental model.", "url": "1-4-mental-models.html#14-02", "sub": "1.4 Mental Models"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "14/03", "title": "Maintain consistent behavior to keep users’ mental models stable.", "body": "Similar actions must produce similar results across contexts.", "url": "1-4-mental-models.html#14-03", "sub": "1.4 Mental Models"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "14/04", "title": "Make causality visible and traceable.", "body": "Users must be able to perceive how actions lead to outcomes.", "url": "1-4-mental-models.html#14-04", "sub": "1.4 Mental Models"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "14/05", "title": "Make states visible when they influence behavior or outcome.", "body": "Avoid hidden conditions, as they corrupt learned mental models.", "url": "1-4-mental-models.html#14-05", "sub": "1.4 Mental Models"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "14/06", "title": "Design for behavioral coherence rather than technical convenience.", "body": "Prioritize behavior that is intuitive to users over internal system logic.", "url": "1-4-mental-models.html#14-06", "sub": "1.4 Mental Models"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "14/07", "title": "Make behavioral deviations explicit and justified.", "body": "Do not introduce unannounced changes to established patterns.", "url": "1-4-mental-models.html#14-07", "sub": "1.4 Mental Models"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "14/08", "title": "Design metaphors that reinforce correct mental models.", "body": "Avoid metaphors that teach incorrect rules about system behavior.", "url": "1-4-mental-models.html#14-08", "sub": "1.4 Mental Models"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "14/09", "title": "Design mental models that support recovery and transfer.", "body": "Ensure users can use their understanding to correct errors and apply knowledge across contexts.", "url": "1-4-mental-models.html#14-09", "sub": "1.4 Mental Models"}, {"t": "s", "c": 1, "ch": "Human Cognition & Behavior", "id": "1.5", "title": "Metaphors", "body": "How abstract systems become understandable.", "url": "1-5-metaphors.html"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "15/01", "title": "Use metaphors only to improve understanding.", "body": "Do not introduce metaphors solely for aesthetic purposes that do not clarify system behavior.", "url": "1-5-metaphors.html#15-01", "sub": "1.5 Metaphors"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "15/02", "title": "Ensure metaphors support accurate reasoning.", "body": "Allow users to infer correct behavior from metaphors, not merely recognize them, and avoid metaphors that introduce false constraints or misleading expectations.", "url": "1-5-metaphors.html#15-02", "sub": "1.5 Metaphors"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "15/03", "title": "Repealed", "body": "Repealed—merged into 15/02", "url": "1-5-metaphors.html#15-03", "sub": "1.5 Metaphors"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "15/04", "title": "Prioritize functional clarity over literal realism.", "body": "Choose metaphors that reveal structure and causality.", "url": "1-5-metaphors.html#15-04", "sub": "1.5 Metaphors"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "15/05", "title": "Align metaphors with actual system consequences.", "body": "Do not allow metaphorical framing to suggest outcomes the system cannot produce.", "url": "1-5-metaphors.html#15-05", "sub": "1.5 Metaphors"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "15/06", "title": "Make the limits of metaphors clear through behavior.", "body": "Ensure users are not surprised when the system diverges from metaphorical expectations.", "url": "1-5-metaphors.html#15-06", "sub": "1.5 Metaphors"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "15/07", "title": "Remove metaphors that create false confidence.", "body": "Avoid metaphorical framing that increases misunderstanding or overconfidence.", "url": "1-5-metaphors.html#15-07", "sub": "1.5 Metaphors"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "15/08", "title": "Support abstract metaphors with strong structural cues.", "body": "Reinforce abstract framing so users can reliably anticipate system behavior.", "url": "1-5-metaphors.html#15-08", "sub": "1.5 Metaphors"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "15/09", "title": "Evolve or abandon metaphors that constrain growth.", "body": "Do not preserve metaphors that obstruct system understanding or capability.", "url": "1-5-metaphors.html#15-09", "sub": "1.5 Metaphors"}, {"t": "s", "c": 1, "ch": "Human Cognition & Behavior", "id": "1.6", "title": "Learnability", "body": "How users progress from novices to competent users.", "url": "1-6-learnability.html"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "16/01", "title": "Design for speed to user competence and ease of growth.", "body": "Measure learnability by how quickly and smoothly users become competent with the system.", "url": "1-6-learnability.html#16-01", "sub": "1.6 Learnability"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "16/02", "title": "Optimize beyond first-use success.", "body": "Ensure early success does not compromise long-term efficiency or mastery.", "url": "1-6-learnability.html#16-02", "sub": "1.6 Learnability"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "16/03", "title": "Enable learning through interaction.", "body": "Design workflows so capability is discovered and reinforced through use rather than dependent on instruction.", "url": "1-6-learnability.html#16-03", "sub": "1.6 Learnability"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "16/04", "title": "Design constraints that enable transition to user autonomy.", "body": "Ensure early guidance supports later independence without structural reset.", "url": "1-6-learnability.html#16-04", "sub": "1.6 Learnability"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "16/05", "title": "Reveal complexity progressively without concealing capability.", "body": "Advanced features must remain discoverable as user competence increases.", "url": "1-6-learnability.html#16-05", "sub": "1.6 Learnability"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "16/06", "title": "Use consistency to facilitate learning transfer.", "body": "Ensure system behaviors and interaction patterns generalize across contexts.", "url": "1-6-learnability.html#16-06", "sub": "1.6 Learnability"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "16/07", "title": "Make errors safe and recoverable.", "body": "Design error handling that encourages user experimentation and reduces hesitation.", "url": "1-6-learnability.html#16-07", "sub": "1.6 Learnability"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "16/08", "title": "Leverage familiar conventions and prior knowledge.", "body": "Align core system behaviors with existing user expectations where appropriate.", "url": "1-6-learnability.html#16-08", "sub": "1.6 Learnability"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "16/09", "title": "Adapt assistance to user competence growth.", "body": "Ensure guidance decreases as user expertise increases, avoiding permanent dependency.", "url": "1-6-learnability.html#16-09", "sub": "1.6 Learnability"}, {"t": "s", "c": 1, "ch": "Human Cognition & Behavior", "id": "1.7", "title": "Simplicity", "body": "An emergent outcome of disciplined design.", "url": "1-7-simplicity.html"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "17/01", "title": "Treat simplicity as a structural outcome, not a visual treatment.", "body": "Design for clarity of structure and workflow rather than surface minimalism.", "url": "1-7-simplicity.html#17-01", "sub": "1.7 Simplicity"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "17/02", "title": "Simplify underlying workflows before simplifying screens.", "body": "Prioritize removing systemic complexity over masking it visually.", "url": "1-7-simplicity.html#17-02", "sub": "1.7 Simplicity"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "17/03", "title": "Reduce decision density rather than feature count.", "body": "Minimize unnecessary user choices within task flows.", "url": "1-7-simplicity.html#17-03", "sub": "1.7 Simplicity"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "17/04", "title": "Keep essential capabilities visible and accessible.", "body": "Do not conceal functionality required for successful use.", "url": "1-7-simplicity.html#17-04", "sub": "1.7 Simplicity"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "17/05", "title": "Do not create cosmetic minimalism by shifting cost to users.", "body": "Ensure system simplicity does not rely on user memory, search, or guesswork.", "url": "1-7-simplicity.html#17-05", "sub": "1.7 Simplicity"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "17/06", "title": "Use progressive disclosure to manage depth without hiding essentials.", "body": "Ensure advanced system capability is accessible without compromising clarity.", "url": "1-7-simplicity.html#17-06", "sub": "1.7 Simplicity"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "17/07", "title": "Ensure predictable and consistent behavior.", "body": "Avoid unexpected outcomes that disrupt user understanding.", "url": "1-7-simplicity.html#17-07", "sub": "1.7 Simplicity"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "17/08", "title": "Preserve user context and continuity.", "body": "Prevent unnecessary context loss across actions and transitions.", "url": "1-7-simplicity.html#17-08", "sub": "1.7 Simplicity"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "17/09", "title": "Design simplicity for sustained interaction.", "body": "Ensure system clarity and user efficiency hold under prolonged use.", "url": "1-7-simplicity.html#17-09", "sub": "1.7 Simplicity"}, {"t": "s", "c": 1, "ch": "Human Cognition & Behavior", "id": "1.8", "title": "Decision-Making", "body": "How users choose between options.", "url": "1-8-decision-making.html"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "18/01", "title": "Limit simultaneous options.", "body": "Present no more choices at once than users can meaningfully compare.", "url": "1-8-decision-making.html#18-01", "sub": "1.8 Decision-Making"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "18/02", "title": "Present options in comparable terms.", "body": "Use the same attributes, units, and order for every option.", "url": "1-8-decision-making.html#18-02", "sub": "1.8 Decision-Making"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "18/03", "title": "Make trade-offs explicit.", "body": "Show what each option gains and what it gives up.", "url": "1-8-decision-making.html#18-03", "sub": "1.8 Decision-Making"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "18/04", "title": "Show consequences before commitment.", "body": "Ensure users see what each choice will do before they make it.", "url": "1-8-decision-making.html#18-04", "sub": "1.8 Decision-Making"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "18/05", "title": "Neutralize choice architecture.", "body": "Do not let order, emphasis, or framing push users toward an option the system prefers.", "url": "1-8-decision-making.html#18-05", "sub": "1.8 Decision-Making"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "18/06", "title": "Allow decisions to be deferred.", "body": "Do not force a choice that the task does not yet require.", "url": "1-8-decision-making.html#18-06", "sub": "1.8 Decision-Making"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "18/07", "title": "Separate consequential decisions from routine ones.", "body": "Make irreversible choices visually and behaviorally distinct.", "url": "1-8-decision-making.html#18-07", "sub": "1.8 Decision-Making"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "18/08", "title": "Keep prior decisions available.", "body": "Let users see what they chose before and why.", "url": "1-8-decision-making.html#18-08", "sub": "1.8 Decision-Making"}, {"t": "d", "c": 1, "ch": "Human Cognition & Behavior", "id": "18/09", "title": "Justify recommendations.", "body": "State the reason for any recommended option and keep alternatives equally reachable.", "url": "1-8-decision-making.html#18-09", "sub": "1.8 Decision-Making"}, {"t": "s", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "2.1", "title": "Information Hierarchy", "body": "What matters most and why.", "url": "2-1-information-hierarchy.html"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "21/01", "title": "Rank information by importance before rendering it.", "body": "Decide what is primary, secondary, and tertiary independent of visual styling; 5.1 governs how that order is shown.", "url": "2-1-information-hierarchy.html#21-01", "sub": "2.1 Information Hierarchy"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "21/02", "title": "Do not flatten unequal information.", "body": "Keep the order of importance intact in structure, sequence, and grouping.", "url": "2-1-information-hierarchy.html#21-02", "sub": "2.1 Information Hierarchy"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "21/03", "title": "Define structural hierarchy before applying visual styling.", "body": "Use typography, spacing, and color to reinforce, not replace, structural priority.", "url": "2-1-information-hierarchy.html#21-03", "sub": "2.1 Information Hierarchy"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "21/04", "title": "Make priority immediately visible.", "body": "Ensure users can identify primary, secondary, and tertiary information without scanning extensively.", "url": "2-1-information-hierarchy.html#21-04", "sub": "2.1 Information Hierarchy"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "21/05", "title": "Group related information to expose relationships.", "body": "Use spatial and structural grouping to reduce interpretation cost.", "url": "2-1-information-hierarchy.html#21-05", "sub": "2.1 Information Hierarchy"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "21/06", "title": "Align visual dominance with user goals.", "body": "Ensure hierarchy reflects user intent, not internal system structure.", "url": "2-1-information-hierarchy.html#21-06", "sub": "2.1 Information Hierarchy"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "21/07", "title": "Adapt hierarchy to context and user task phase.", "body": "Adjust emphasis as user state and goals change to support efficient workflow completion.", "url": "2-1-information-hierarchy.html#21-07", "sub": "2.1 Information Hierarchy"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "21/08", "title": "Use hierarchy to reduce navigation and decision overhead.", "body": "Design layouts so the next action is evident to users without additional exploration.", "url": "2-1-information-hierarchy.html#21-08", "sub": "2.1 Information Hierarchy"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "21/09", "title": "Keep the order of importance stable across views.", "body": "Prevent shifts in priority that force users to relearn where key information lives.", "url": "2-1-information-hierarchy.html#21-09", "sub": "2.1 Information Hierarchy"}, {"t": "s", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "2.2", "title": "Discoverability", "body": "What systems reveal they can do.", "url": "2-2-discoverability.html"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "22/01", "title": "Ensure all necessary capabilities are visibly accessible.", "body": "Accelerate confident engagement and product adoption by helping users quickly understand what they can do without training.", "url": "2-2-discoverability.html#22-01", "sub": "2.2 Discoverability"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "22/02", "title": "Repealed", "body": "Repealed—merged into 32/02", "url": "2-2-discoverability.html#22-02", "sub": "2.2 Discoverability"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "22/03", "title": "Repealed", "body": "Repealed—merged into 32/03", "url": "2-2-discoverability.html#22-03", "sub": "2.2 Discoverability"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "22/04", "title": "Use hidden or gesture-based interactions only with explicit signaling.", "body": "Prevent discoverability issues for essential tasks by ensuring users know those actions exist.", "url": "2-2-discoverability.html#22-04", "sub": "2.2 Discoverability"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "22/05", "title": "Surface actions when they become relevant.", "body": "Ensure users can discover appropriate actions within context rather than through explanation.", "url": "2-2-discoverability.html#22-05", "sub": "2.2 Discoverability"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "22/06", "title": "Ensure progressive disclosure does not obscure access.", "body": "Advanced capability must remain clearly reachable as complexity unfolds.", "url": "2-2-discoverability.html#22-06", "sub": "2.2 Discoverability"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "22/07", "title": "Design for intentional discovery.", "body": "Make critical functionality directly discoverable, not dependent on chance exploration.", "url": "2-2-discoverability.html#22-07", "sub": "2.2 Discoverability"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "22/08", "title": "Prioritize discoverability before optimizing efficiency.", "body": "Ensure actionable elements are found reliably before improving speed.", "url": "2-2-discoverability.html#22-08", "sub": "2.2 Discoverability"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "22/09", "title": "Design discoverability to build user confidence.", "body": "Guide users so they feel a sense of mastery and control over product capabilities.", "url": "2-2-discoverability.html#22-09", "sub": "2.2 Discoverability"}, {"t": "s", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "2.3", "title": "Navigation", "body": "How users move and stay oriented.", "url": "2-3-navigation.html"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "23/01", "title": "Design navigation to preserve orientation at all times.", "body": "Ensure user movement never compromises users’ understanding of where they are.", "url": "2-3-navigation.html#23-01", "sub": "2.3 Navigation"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "23/02", "title": "Make current location continuously visible.", "body": "Do not require users to infer their position within the navigation structure.", "url": "2-3-navigation.html#23-02", "sub": "2.3 Navigation"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "23/03", "title": "Expose navigational structure perceptually.", "body": "Ensure users can perceive hierarchy and relationships without memorization.", "url": "2-3-navigation.html#23-03", "sub": "2.3 Navigation"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "23/04", "title": "Make navigation controls visually and behaviorally explicit.", "body": "Avoid ambiguous elements that obscure navigation options.", "url": "2-3-navigation.html#23-04", "sub": "2.3 Navigation"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "23/05", "title": "Limit navigational depth and complexity.", "body": "Favor breadth with clarity over deeply nested structures.", "url": "2-3-navigation.html#23-05", "sub": "2.3 Navigation"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "23/06", "title": "Favor stable places over constant movement.", "body": "Bring tools and content to users rather than forcing them to relocate.", "url": "2-3-navigation.html#23-06", "sub": "2.3 Navigation"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "23/07", "title": "Maintain user context across navigation.", "body": "Ensure state, progress, and understanding persist during transitions.", "url": "2-3-navigation.html#23-07", "sub": "2.3 Navigation"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "23/08", "title": "Prioritize orientation over mere reachability.", "body": "Maintain users’ sense of orientation even after they reach their destination.", "url": "2-3-navigation.html#23-08", "sub": "2.3 Navigation"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "23/09", "title": "Design navigation to recede as mastery develops.", "body": "Empower users’ expertise while keeping navigation unobtrusive.", "url": "2-3-navigation.html#23-09", "sub": "2.3 Navigation"}, {"t": "s", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "2.4", "title": "Progressive Disclosure", "body": "How complexity is revealed safely.", "url": "2-4-progressive-disclosure.html"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "24/01", "title": "Treat progressive disclosure as a timing strategy.", "body": "Manage when complexity is exposed to users rather than hiding it.", "url": "2-4-progressive-disclosure.html#24-01", "sub": "2.4 Progressive Disclosure"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "24/02", "title": "Never defer what the current task requires.", "body": "Disclose progressively only what the task does not need now.", "url": "2-4-progressive-disclosure.html#24-02", "sub": "2.4 Progressive Disclosure"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "24/03", "title": "Allow users to control when deeper complexity is revealed.", "body": "Avoid automatic or unexpected expansion of interface depth.", "url": "2-4-progressive-disclosure.html#24-03", "sub": "2.4 Progressive Disclosure"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "24/04", "title": "Make additional depth perceptible and predictable.", "body": "Signal further capabilities clearly, enabling users to prepare adequately.", "url": "2-4-progressive-disclosure.html#24-04", "sub": "2.4 Progressive Disclosure"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "24/05", "title": "Design early layers to scaffold later complexity.", "body": "Ensure initial views introduce structures and concepts that are reused at deeper levels.", "url": "2-4-progressive-disclosure.html#24-05", "sub": "2.4 Progressive Disclosure"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "24/06", "title": "Ensure deeper functionality remains clearly reachable.", "body": "Prevent burying advanced capability behind obscure paths.", "url": "2-4-progressive-disclosure.html#24-06", "sub": "2.4 Progressive Disclosure"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "24/07", "title": "Preserve context across progressive disclosures.", "body": "Do not require users to mentally reconstruct hidden information when expanding or collapsing views.", "url": "2-4-progressive-disclosure.html#24-07", "sub": "2.4 Progressive Disclosure"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "24/08", "title": "Allow complexity to be deferred without cost.", "body": "Ensure users can postpone advanced learning without blocking progress.", "url": "2-4-progressive-disclosure.html#24-08", "sub": "2.4 Progressive Disclosure"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "24/09", "title": "Maintain consistent progressive disclosure patterns.", "body": "Use predictable reveal mechanisms across contexts and screens.", "url": "2-4-progressive-disclosure.html#24-09", "sub": "2.4 Progressive Disclosure"}, {"t": "s", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "2.5", "title": "State", "body": "What a system remembers for users.", "url": "2-5-state.html"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "25/01", "title": "Design state to offload user memory.", "body": "Ensure the system remembers context so users do not have to reconstruct it.", "url": "2-5-state.html#25-01", "sub": "2.5 State"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "25/02", "title": "Make outcome-relevant state visible.", "body": "Do not allow hidden conditions to influence results without perceptible indications.", "url": "2-5-state.html#25-02", "sub": "2.5 State"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "25/03", "title": "Make sure state is inspectable.", "body": "Ensure users can view and understand the state that affects their work.", "url": "2-5-state.html#25-03", "sub": "2.5 State"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "25/04", "title": "Differentiate state types explicitly.", "body": "Distinguish local, session, and persistent states in both behavior and presentation.", "url": "2-5-state.html#25-04", "sub": "2.5 State"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "25/05", "title": "Signal all meaningful state changes.", "body": "Prevent modifications to state without clear and timely feedback.", "url": "2-5-state.html#25-05", "sub": "2.5 State"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "25/06", "title": "Make state reversible and resettable.", "body": "Provide clear mechanisms to modify or undo stored context.", "url": "2-5-state.html#25-06", "sub": "2.5 State"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "25/07", "title": "Persist state across interruptions.", "body": "Ensure work and context survive pauses, navigation, and session breaks.", "url": "2-5-state.html#25-07", "sub": "2.5 State"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "25/08", "title": "Align remembered state with user intent.", "body": "Do not preserve or apply state that contradicts user expectations or goals.", "url": "2-5-state.html#25-08", "sub": "2.5 State"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "25/09", "title": "Treat state as protected user data.", "body": "Apply integrity, security, and privacy safeguards to stored context.", "url": "2-5-state.html#25-09", "sub": "2.5 State"}, {"t": "s", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "2.6", "title": "Explorability", "body": "How users learn through safe exploration.", "url": "2-6-explorability.html"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "26/01", "title": "Ensure exploration is safe by design.", "body": "Safeguard users from any risk of irreversible damage or loss while exploring the product.", "url": "2-6-explorability.html#26-01", "sub": "2.6 Explorability"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "26/02", "title": "Provide strong recovery mechanisms.", "body": "Support undo, previews, and reversibility as structural prerequisites for exploration.", "url": "2-6-explorability.html#26-02", "sub": "2.6 Explorability"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "26/03", "title": "Keep exploration optional for task completion.", "body": "Ensure essential workflows function independently of hidden discoveries.", "url": "2-6-explorability.html#26-03", "sub": "2.6 Explorability"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "26/04", "title": "Provide stable landmarks for orientation.", "body": "Allow users to identify their location and return paths during exploration.", "url": "2-6-explorability.html#26-04", "sub": "2.6 Explorability"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "26/05", "title": "Make system boundaries explicit.", "body": "Reveal limits, constraints, and unavailable paths clearly.", "url": "2-6-explorability.html#26-05", "sub": "2.6 Explorability"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "26/06", "title": "Foster user learning through interaction and its consequences.", "body": "Design exploration so users develop understanding through visible cause and effect.", "url": "2-6-explorability.html#26-06", "sub": "2.6 Explorability"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "26/07", "title": "Leverage exploration to reveal system structure.", "body": "Ensure discovery reinforces conceptual understanding rather than just isolated feature exposure.", "url": "2-6-explorability.html#26-07", "sub": "2.6 Explorability"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "26/08", "title": "Allow multiple valid paths where appropriate.", "body": "Support flexible interaction paths without compromising clarity.", "url": "2-6-explorability.html#26-08", "sub": "2.6 Explorability"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "26/09", "title": "Preserve state integrity during exploration.", "body": "Ensure experimentation does not disrupt context or create unintended side effects.", "url": "2-6-explorability.html#26-09", "sub": "2.6 Explorability"}, {"t": "s", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "2.7", "title": "Search & Labeling", "body": "How users find what they cannot see.", "url": "2-7-search-and-labeling.html"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "27/01", "title": "Label in the users’ vocabulary.", "body": "Name content and actions with the terms users use, not internal or technical terms.", "url": "2-7-search-and-labeling.html#27-01", "sub": "2.7 Search & Labeling"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "27/02", "title": "Keep labels stable and unique.", "body": "Use one label for one thing across the system.", "url": "2-7-search-and-labeling.html#27-02", "sub": "2.7 Search & Labeling"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "27/03", "title": "Provide search where navigation cannot scale.", "body": "Offer search when content outgrows what navigation can expose.", "url": "2-7-search-and-labeling.html#27-03", "sub": "2.7 Search & Labeling"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "27/04", "title": "Make search forgiving.", "body": "Match misspellings, synonyms, and partial queries.", "url": "2-7-search-and-labeling.html#27-04", "sub": "2.7 Search & Labeling"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "27/05", "title": "Show search scope.", "body": "Indicate what is being searched and which filters apply.", "url": "2-7-search-and-labeling.html#27-05", "sub": "2.7 Search & Labeling"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "27/06", "title": "Rank by task relevance.", "body": "Order results by what the user most likely needs, not by storage order.", "url": "2-7-search-and-labeling.html#27-06", "sub": "2.7 Search & Labeling"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "27/07", "title": "Give results enough context.", "body": "Show the information needed to choose a result without opening it.", "url": "2-7-search-and-labeling.html#27-07", "sub": "2.7 Search & Labeling"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "27/08", "title": "Make empty results actionable.", "body": "Suggest corrections, broader scopes, or alternative paths.", "url": "2-7-search-and-labeling.html#27-08", "sub": "2.7 Search & Labeling"}, {"t": "d", "c": 2, "ch": "Information Architecture & Wayfinding", "id": "27/09", "title": "Align search with navigation.", "body": "Ensure search results respect the same permissions, states, and labels as navigation.", "url": "2-7-search-and-labeling.html#27-09", "sub": "2.7 Search & Labeling"}, {"t": "s", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "3.1", "title": "Human-Interface Objects", "body": "What users act upon.", "url": "3-1-human-interface-objects.html"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "31/01", "title": "Design interaction around user-reasonable objects.", "body": "Structure the interface according to objects users can reason about.", "url": "3-1-human-interface-objects.html#31-01", "sub": "3.1 Human-Interface Objects"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "31/02", "title": "Model objects for user reasoning, not system storage.", "body": "Expose conceptual objects that align with user understanding rather than internal data structures.", "url": "3-1-human-interface-objects.html#31-02", "sub": "3.1 Human-Interface Objects"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "31/03", "title": "Ensure each object has a clear and stable identity.", "body": "Do not assign multiple conflicting meanings to a single object.", "url": "3-1-human-interface-objects.html#31-03", "sub": "3.1 Human-Interface Objects"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "31/04", "title": "Make meaningful objects visible or inspectable.", "body": "Avoid invisible entities in core interactions.", "url": "3-1-human-interface-objects.html#31-04", "sub": "3.1 Human-Interface Objects"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "31/05", "title": "Align actions with object type.", "body": "Ensure available actions are consistent with the object’s conceptual identity.", "url": "3-1-human-interface-objects.html#31-05", "sub": "3.1 Human-Interface Objects"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "31/06", "title": "Separate objects when behavior diverges.", "body": "Do not overload one object with incompatible interaction rules.", "url": "3-1-human-interface-objects.html#31-06", "sub": "3.1 Human-Interface Objects"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "31/07", "title": "Ensure behavior reinforces object identity.", "body": "Use consistent interaction patterns to teach what an object represents.", "url": "3-1-human-interface-objects.html#31-07", "sub": "3.1 Human-Interface Objects"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "31/08", "title": "Maintain predictable object behavior over time.", "body": "Do not alter interaction rules for established objects.", "url": "3-1-human-interface-objects.html#31-08", "sub": "3.1 Human-Interface Objects"}, {"t": "s", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "3.2", "title": "Affordances", "body": "How action is perceived.", "url": "3-2-affordances.html"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "32/01", "title": "Design affordances to be perceptually evident.", "body": "Ensure users can immediately understand possible actions without instruction.", "url": "3-2-affordances.html#32-01", "sub": "3.2 Affordances"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "32/02", "title": "Provide clear signifiers for all actionable elements.", "body": "Attach meaningful visual cues to all interactive elements to clearly convey their affordances.", "url": "3-2-affordances.html#32-02", "sub": "3.2 Affordances"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "32/03", "title": "Make interactive elements visually distinguishable.", "body": "Use deliberate styling and spacing to clearly distinguish interactive elements from informational content.", "url": "3-2-affordances.html#32-03", "sub": "3.2 Affordances"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "32/04", "title": "Eliminate false affordances.", "body": "Do not present elements as interactive if they do not respond to action.", "url": "3-2-affordances.html#32-04", "sub": "3.2 Affordances"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "32/05", "title": "Visually distinguish unavailable actions.", "body": "Ensure disabled or inapplicable options are clearly indicated.", "url": "3-2-affordances.html#32-05", "sub": "3.2 Affordances"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "32/06", "title": "Maintain consistent affordance patterns.", "body": "Use uniform visual and behavioral cues for similar actions.", "url": "3-2-affordances.html#32-06", "sub": "3.2 Affordances"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "32/07", "title": "Enable safe action before full understanding.", "body": "Design affordances so users can act confidently without prior conceptual mastery.", "url": "3-2-affordances.html#32-07", "sub": "3.2 Affordances"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "32/08", "title": "Use affordances to minimize memory and guesswork.", "body": "Leverage clear affordances to reduce cognitive load so users do not have to recall.", "url": "3-2-affordances.html#32-08", "sub": "3.2 Affordances"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "32/09", "title": "Ensure affordances remain legible as complexity increases.", "body": "Prevent action cues from degrading under density or scale.", "url": "3-2-affordances.html#32-09", "sub": "3.2 Affordances"}, {"t": "s", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "3.3", "title": "Direct Manipulation", "body": "How action is executed.", "url": "3-3-direct-manipulation.html"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "33/01", "title": "Design interactions around visible objects.", "body": "Build interactions on objects that users can see and understand, not hidden or abstract commands.", "url": "3-3-direct-manipulation.html#33-01", "sub": "3.3 Direct Manipulation"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "33/02", "title": "Minimize abstraction between intent and action.", "body": "Reduce mental translation required to achieve outcomes.", "url": "3-3-direct-manipulation.html#33-02", "sub": "3.3 Direct Manipulation"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "33/03", "title": "Make scope and consequence visible before action.", "body": "Ensure users understand what will be affected prior to execution.", "url": "3-3-direct-manipulation.html#33-03", "sub": "3.3 Direct Manipulation"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "33/04", "title": "Provide immediate and continuous feedback.", "body": "Maintain tight feedback loops during user manipulation.", "url": "3-3-direct-manipulation.html#33-04", "sub": "3.3 Direct Manipulation"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "33/05", "title": "Ensure responsive interaction latency.", "body": "Preserve the perception of control through timely system response.", "url": "3-3-direct-manipulation.html#33-05", "sub": "3.3 Direct Manipulation"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "33/06", "title": "Match required precision to consequence.", "body": "Avoid demanding fine motor accuracy for low-risk or common actions.", "url": "3-3-direct-manipulation.html#33-06", "sub": "3.3 Direct Manipulation"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "33/07", "title": "Minimize or eliminate hidden interaction modes.", "body": "Ensure users do not unknowingly switch behavioral contexts.", "url": "3-3-direct-manipulation.html#33-07", "sub": "3.3 Direct Manipulation"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "33/08", "title": "Make actions reversible.", "body": "Provide reliable undo or recovery mechanisms.", "url": "3-3-direct-manipulation.html#33-08", "sub": "3.3 Direct Manipulation"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "33/09", "title": "Favor reversibility over confirmation gating.", "body": "Design systems so undo replaces excessive confirmation dialogs.", "url": "3-3-direct-manipulation.html#33-09", "sub": "3.3 Direct Manipulation"}, {"t": "s", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "3.4", "title": "Feedback", "body": "How action is confirmed.", "url": "3-4-feedback.html"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "34/01", "title": "Acknowledge every user action.", "body": "Ensure all meaningful actions produce visible system responses.", "url": "3-4-feedback.html#34-01", "sub": "3.4 Feedback"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "34/02", "title": "Provide immediate acknowledgment.", "body": "Respond to actions without delay to prevent duplicate input and uncertainty.", "url": "3-4-feedback.html#34-02", "sub": "3.4 Feedback"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "34/03", "title": "Confirm user intent explicitly.", "body": "Indicate the system understood and accepted the intended action.", "url": "3-4-feedback.html#34-03", "sub": "3.4 Feedback"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "34/04", "title": "Ensure feedback conveys meaningful outcome.", "body": "Communicate what changed or occurred, not merely that activity happened.", "url": "3-4-feedback.html#34-04", "sub": "3.4 Feedback"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "34/05", "title": "Make scope and consequence explicit in feedback.", "body": "Clarify what was affected before and after execution.", "url": "3-4-feedback.html#34-05", "sub": "3.4 Feedback"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "34/06", "title": "Differentiate feedback by outcome.", "body": "Use distinct signals for success, partial completion, warning, and failure states.", "url": "3-4-feedback.html#34-06", "sub": "3.4 Feedback"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "34/07", "title": "Ensure feedback is accurate and proportional.", "body": "Prevent conveying false accuracy or overconfidence.", "url": "3-4-feedback.html#34-07", "sub": "3.4 Feedback"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "34/08", "title": "Persist critical feedback until resolved.", "body": "Do not allow essential information to disappear prematurely.", "url": "3-4-feedback.html#34-08", "sub": "3.4 Feedback"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "34/09", "title": "Provide recovery guidance within feedback.", "body": "Offer clear next steps when errors or exceptions occur.", "url": "3-4-feedback.html#34-09", "sub": "3.4 Feedback"}, {"t": "s", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "3.5", "title": "User Efficiency", "body": "Why interaction quality matters.", "url": "3-5-user-efficiency.html"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "35/01", "title": "Prioritize human time as the primary cost.", "body": "Favor design decisions that save user time over system convenience.", "url": "3-5-user-efficiency.html#35-01", "sub": "3.5 User Efficiency"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "35/02", "title": "Evaluate efficiency across complete workflows.", "body": "Optimize full task completion time, not isolated interaction speed.", "url": "3-5-user-efficiency.html#35-02", "sub": "3.5 User Efficiency"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "35/03", "title": "Optimize for user throughput.", "body": "Reduce friction that slows progress regardless of system performance metrics.", "url": "3-5-user-efficiency.html#35-03", "sub": "3.5 User Efficiency"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "35/04", "title": "Prevent redundant or corrective input.", "body": "Cut re-entry, unnecessary formatting, and avoidable corrections.", "url": "3-5-user-efficiency.html#35-04", "sub": "3.5 User Efficiency"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "35/05", "title": "Remove blocking latency wherever possible.", "body": "Eliminate preventable delays that interrupt task flow and break user momentum.", "url": "3-5-user-efficiency.html#35-05", "sub": "3.5 User Efficiency"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "35/06", "title": "Preserve clarity while optimizing speed.", "body": "Ensure acceleration does not reduce understanding.", "url": "3-5-user-efficiency.html#35-06", "sub": "3.5 User Efficiency"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "35/07", "title": "Use automation to reduce user steps.", "body": "Avoid introducing automation that increases monitoring or correction burden.", "url": "3-5-user-efficiency.html#35-07", "sub": "3.5 User Efficiency"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "35/08", "title": "Design to minimize error and recovery cost.", "body": "Account for correction time as part of user efficiency.", "url": "3-5-user-efficiency.html#35-08", "sub": "3.5 User Efficiency"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "35/09", "title": "Optimize efficiency for prolonged use.", "body": "Ensure productivity remains high during extended interaction.", "url": "3-5-user-efficiency.html#35-09", "sub": "3.5 User Efficiency"}, {"t": "s", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "3.6", "title": "Fitts’s Law", "body": "The governing physical constraint on all interaction.", "url": "3-6-fitts-law.html"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "36/01", "title": "Minimize distance to high-frequency targets.", "body": "Place commonly used controls within short motor reach.", "url": "3-6-fitts-law.html#36-01", "sub": "3.6 Fitts’s Law"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "36/02", "title": "Size interactive targets according to frequency and consequence.", "body": "Make important or frequent actions larger and easier to acquire.", "url": "3-6-fitts-law.html#36-02", "sub": "3.6 Fitts’s Law"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "36/03", "title": "Avoid unnecessary precision requirements.", "body": "Do not require fine motor accuracy for routine or low-risk actions.", "url": "3-6-fitts-law.html#36-03", "sub": "3.6 Fitts’s Law"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "36/04", "title": "Use screen edges strategically for frequent or critical actions.", "body": "Leverage boundaries to reduce motor effort.", "url": "3-6-fitts-law.html#36-04", "sub": "3.6 Fitts’s Law"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "36/05", "title": "Align target accessibility with usage frequency and importance.", "body": "Ensure high-value actions are easiest to acquire.", "url": "3-6-fitts-law.html#36-05", "sub": "3.6 Fitts’s Law"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "36/06", "title": "Reduce unnecessary target acquisitions.", "body": "Eliminate redundant steps to decrease total motor effort.", "url": "3-6-fitts-law.html#36-06", "sub": "3.6 Fitts’s Law"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "36/07", "title": "Prioritize motor efficiency over visual symmetry.", "body": "Design layouts according to acquisition performance, not aesthetic balance alone.", "url": "3-6-fitts-law.html#36-07", "sub": "3.6 Fitts’s Law"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "36/08", "title": "Adapt target design to input modality.", "body": "Account for device-specific motor constraints in layout and sizing decisions.", "url": "3-6-fitts-law.html#36-08", "sub": "3.6 Fitts’s Law"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "36/09", "title": "Optimize for cumulative motor efficiency.", "body": "Design to reduce repeated acquisition costs during sustained use.", "url": "3-6-fitts-law.html#36-09", "sub": "3.6 Fitts’s Law"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "36/10", "title": "Apply motor performance principles proactively.", "body": "Use Fitts’s Law to inform design decisions before usability testing.", "url": "3-6-fitts-law.html#36-10", "sub": "3.6 Fitts’s Law"}, {"t": "s", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "3.7", "title": "Input", "body": "How users enter information.", "url": "3-7-input.html"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "37/01", "title": "Ask only for what is needed.", "body": "Do not request information the system already has or does not use.", "url": "3-7-input.html#37-01", "sub": "3.7 Input"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "37/02", "title": "Accept natural formats.", "body": "Parse common ways users express dates, numbers, names, and addresses.", "url": "3-7-input.html#37-02", "sub": "3.7 Input"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "37/03", "title": "Show constraints before entry.", "body": "State limits, formats, and requirements before users type.", "url": "3-7-input.html#37-03", "sub": "3.7 Input"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "37/04", "title": "Validate early without interrupting.", "body": "Check input as it is completed, not on submission and not on every keystroke.", "url": "3-7-input.html#37-04", "sub": "3.7 Input"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "37/05", "title": "Locate errors at their source.", "body": "Indicate the exact field and the correction needed.", "url": "3-7-input.html#37-05", "sub": "3.7 Input"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "37/06", "title": "Match the control to the data.", "body": "Use the input method that fits the type, range, and frequency of the value.", "url": "3-7-input.html#37-06", "sub": "3.7 Input"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "37/07", "title": "Preserve entered data.", "body": "Keep all valid input through errors, navigation, and interruptions.", "url": "3-7-input.html#37-07", "sub": "3.7 Input"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "37/08", "title": "Distinguish required from optional.", "body": "Mark which input is needed to proceed.", "url": "3-7-input.html#37-08", "sub": "3.7 Input"}, {"t": "d", "c": 3, "ch": "Interaction Mechanics & Agency", "id": "37/09", "title": "Separate suggested input from entered input.", "body": "Make autofill and predictions visible as suggestions until users accept them.", "url": "3-7-input.html#37-09", "sub": "3.7 Input"}, {"t": "s", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "4.1", "title": "Defaults", "body": "What a system chooses on users’ behalf.", "url": "4-1-defaults.html"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "41/01", "title": "Treat defaults as intentional decisions.", "body": "Design every default as a behavioral commitment, not a temporary filler.", "url": "4-1-defaults.html#41-01", "sub": "4.1 Defaults"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "41/02", "title": "Use defaults to remove effort.", "body": "Make sure defaults reduce user workload, not introduce hesitation.", "url": "4-1-defaults.html#41-02", "sub": "4.1 Defaults"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "41/03", "title": "Make default implications explicit.", "body": "Ensure users understand what accepting a default will do.", "url": "4-1-defaults.html#41-03", "sub": "4.1 Defaults"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "41/04", "title": "Clarify the scope of default effects.", "body": "Indicate whether a default applies locally, globally, or persistently.", "url": "4-1-defaults.html#41-04", "sub": "4.1 Defaults"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "41/05", "title": "Ensure defaults are easily overridable.", "body": "Allow users to change defaults without friction.", "url": "4-1-defaults.html#41-05", "sub": "4.1 Defaults"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "41/06", "title": "Protect user work when defaults change.", "body": "Prevent silent data loss or destructive resets triggered by defaults.", "url": "4-1-defaults.html#41-06", "sub": "4.1 Defaults"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "41/07", "title": "Adapt defaults to context when appropriate.", "body": "Use task or environment signals to refine default values responsibly.", "url": "4-1-defaults.html#41-07", "sub": "4.1 Defaults"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "41/08", "title": "Remove unreliable or misleading defaults.", "body": "Eliminate defaults that users consistently correct.", "url": "4-1-defaults.html#41-08", "sub": "4.1 Defaults"}, {"t": "s", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "4.2", "title": "Anticipation", "body": "What a system brings forward proactively.", "url": "4-2-anticipation.html"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "42/01", "title": "Use anticipation to reduce user effort.", "body": "Design anticipatory behavior to remove friction rather than demonstrate intelligence.", "url": "4-2-anticipation.html#42-01", "sub": "4.2 Anticipation"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "42/02", "title": "Preserve user control in anticipatory features.", "body": "Offer suggestions rather than automatic irreversible decisions.", "url": "4-2-anticipation.html#42-02", "sub": "4.2 Anticipation"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "42/03", "title": "Make anticipatory behavior perceptible.", "body": "Ensure users recognize when the system is assisting or predicting.", "url": "4-2-anticipation.html#42-03", "sub": "4.2 Anticipation"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "42/04", "title": "Deliver anticipation at the moment of relevance.", "body": "Trigger assistance only when it meaningfully supports the current task phase.", "url": "4-2-anticipation.html#42-04", "sub": "4.2 Anticipation"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "42/05", "title": "Base anticipation on current context.", "body": "Use task, state, and history signals to ensure relevance.", "url": "4-2-anticipation.html#42-05", "sub": "4.2 Anticipation"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "42/06", "title": "Limit anticipatory interventions.", "body": "Do not overwhelm with excessive or unnecessary suggestions.", "url": "4-2-anticipation.html#42-06", "sub": "4.2 Anticipation"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "42/07", "title": "Ensure anticipatory assistance is optional.", "body": "Allow users to dismiss or ignore suggestions without penalty.", "url": "4-2-anticipation.html#42-07", "sub": "4.2 Anticipation"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "42/08", "title": "Minimize the cost of incorrect anticipation.", "body": "Ensure mistaken suggestions are easy to ignore or reverse.", "url": "4-2-anticipation.html#42-08", "sub": "4.2 Anticipation"}, {"t": "s", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "4.3", "title": "Autonomy", "body": "How much control users retain.", "url": "4-3-autonomy.html"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "43/01", "title": "Design system behavior to preserve human agency.", "body": "Ensure automation supports rather than replaces user decision-making.", "url": "4-3-autonomy.html#43-01", "sub": "4.3 Autonomy"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "43/02", "title": "Require explicit delegation of automated behavior.", "body": "Do not perform consequential automation without user awareness and consent.", "url": "4-3-autonomy.html#43-02", "sub": "4.3 Autonomy"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "43/03", "title": "Provide meaningful intervention mechanisms.", "body": "Enable users to override, pause, or modify automated processes.", "url": "4-3-autonomy.html#43-03", "sub": "4.3 Autonomy"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "43/04", "title": "Make automated state and intent visible.", "body": "Ensure users understand what the system is doing and why.", "url": "4-3-autonomy.html#43-04", "sub": "4.3 Autonomy"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "43/05", "title": "Ensure reversibility of automated outcomes.", "body": "Allow users to undo or revise system-initiated actions.", "url": "4-3-autonomy.html#43-05", "sub": "4.3 Autonomy"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "43/06", "title": "Calibrate autonomy according to risk level.", "body": "Increase user control requirements as consequence severity rises.", "url": "4-3-autonomy.html#43-06", "sub": "4.3 Autonomy"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "43/07", "title": "Prioritize agency over raw efficiency.", "body": "Avoid enforcing automation solely for speed gains.", "url": "4-3-autonomy.html#43-07", "sub": "4.3 Autonomy"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "43/08", "title": "Preserve autonomy across time horizons.", "body": "Enable users to inspect and adjust persistent settings and historical automation.", "url": "4-3-autonomy.html#43-08", "sub": "4.3 Autonomy"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "43/09", "title": "Design automation to reinforce user confidence.", "body": "Ensure system behavior strengthens users’ sense of control and capability.", "url": "4-3-autonomy.html#43-09", "sub": "4.3 Autonomy"}, {"t": "s", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "4.4", "title": "Error Prevention", "body": "How mistakes are avoided.", "url": "4-4-error-prevention.html"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "44/01", "title": "Design to prevent errors proactively.", "body": "Prioritize structural prevention over post-error recovery.", "url": "4-4-error-prevention.html#44-01", "sub": "4.4 Error Prevention"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "44/02", "title": "Eliminate invalid states through constraint.", "body": "Prevent users from entering configurations that cannot succeed.", "url": "4-4-error-prevention.html#44-02", "sub": "4.4 Error Prevention"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "44/03", "title": "Make safe and correct actions easiest to perform.", "body": "Design workflows so desirable behavior requires the least effort.", "url": "4-4-error-prevention.html#44-03", "sub": "4.4 Error Prevention"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "44/04", "title": "Surface potential errors at the earliest viable moment.", "body": "Provide validation before consequences escalate.", "url": "4-4-error-prevention.html#44-04", "sub": "4.4 Error Prevention"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "44/05", "title": "Eliminate or minimize hidden modes.", "body": "Ensure users are not required to remember invisible states to avoid errors.", "url": "4-4-error-prevention.html#44-05", "sub": "4.4 Error Prevention"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "44/06", "title": "Adjust safeguards according to consequence severity.", "body": "Increase friction proportionally for high-risk actions.", "url": "4-4-error-prevention.html#44-06", "sub": "4.4 Error Prevention"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "44/07", "title": "Use confirmation dialogs sparingly and meaningfully.", "body": "Avoid habituating users to dismiss warnings automatically.", "url": "4-4-error-prevention.html#44-07", "sub": "4.4 Error Prevention"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "44/08", "title": "Allow safe exploration without penalty.", "body": "Design guardrails that protect without discouraging learning.", "url": "4-4-error-prevention.html#44-08", "sub": "4.4 Error Prevention"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "44/09", "title": "Ensure defaults and automation reduce error risk.", "body": "Design automated behavior to minimize harm and clarify consequences.", "url": "4-4-error-prevention.html#44-09", "sub": "4.4 Error Prevention"}, {"t": "s", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "4.5", "title": "Recovery", "body": "How mistakes are repaired.", "url": "4-5-recovery.html"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "45/01", "title": "Design with failure as an expected condition.", "body": "Build recovery mechanisms as core workflow features.", "url": "4-5-recovery.html#45-01", "sub": "4.5 Recovery"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "45/02", "title": "Provide reliable undo functionality.", "body": "Ensure undo is consistent, predictable, and comprehensive.", "url": "4-5-recovery.html#45-02", "sub": "4.5 Recovery"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "45/03", "title": "Maximize reversibility of user actions.", "body": "Design systems so users can act without fear of permanent harm.", "url": "4-5-recovery.html#45-03", "sub": "4.5 Recovery"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "45/04", "title": "Protect user data during recovery.", "body": "Prevent loss of work during error correction or failure events.", "url": "4-5-recovery.html#45-04", "sub": "4.5 Recovery"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "45/05", "title": "Make irreversible actions unmistakably clear.", "body": "Require explicit acknowledgment for permanent consequences.", "url": "4-5-recovery.html#45-05", "sub": "4.5 Recovery"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "45/06", "title": "Preserve context during recovery.", "body": "Ensure users remain oriented after correcting errors.", "url": "4-5-recovery.html#45-06", "sub": "4.5 Recovery"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "45/07", "title": "Provide forward guidance after recovery.", "body": "Enable users to resume progress immediately after correction.", "url": "4-5-recovery.html#45-07", "sub": "4.5 Recovery"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "45/08", "title": "Offer multiple recovery mechanisms.", "body": "Supplement undo with version history, restore points, or alternative correction paths.", "url": "4-5-recovery.html#45-08", "sub": "4.5 Recovery"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "45/09", "title": "Design recovery for interruption scenarios.", "body": "Ensure resilience across crashes, pauses, and connectivity loss.", "url": "4-5-recovery.html#45-09", "sub": "4.5 Recovery"}, {"t": "s", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "4.6", "title": "Work Protection", "body": "How effort is preserved over time.", "url": "4-6-work-protection.html"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "46/01", "title": "Treat user effort as high-value data.", "body": "Design systems to preserve time, thought, and intent embedded in user work.", "url": "4-6-work-protection.html#46-01", "sub": "4.6 Work Protection"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "46/02", "title": "Design for interruption and failure by default.", "body": "Build resilience into workflows as a baseline condition.", "url": "4-6-work-protection.html#46-02", "sub": "4.6 Work Protection"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "46/03", "title": "Implement automatic and continuous saving.", "body": "Do not rely on manual save actions for data preservation.", "url": "4-6-work-protection.html#46-03", "sub": "4.6 Work Protection"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "46/04", "title": "Favor non-destructive workflows.", "body": "Design actions so original work remains recoverable.", "url": "4-6-work-protection.html#46-04", "sub": "4.6 Work Protection"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "46/05", "title": "Require explicit confirmation for destructive actions.", "body": "Make permanent deletion unmistakable and intentional.", "url": "4-6-work-protection.html#46-05", "sub": "4.6 Work Protection"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "46/06", "title": "Protect drafts and intermediate states.", "body": "Preserve partial work throughout task progression.", "url": "4-6-work-protection.html#46-06", "sub": "4.6 Work Protection"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "46/07", "title": "Ensure cross-session and cross-device continuity.", "body": "Maintain work integrity across time and environments.", "url": "4-6-work-protection.html#46-07", "sub": "4.6 Work Protection"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "46/08", "title": "Communicate protection status clearly.", "body": "Provide visible indicators that work is preserved.", "url": "4-6-work-protection.html#46-08", "sub": "4.6 Work Protection"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "46/09", "title": "Integrate recovery into protection systems.", "body": "Ensure preserved work can be restored or rolled back reliably.", "url": "4-6-work-protection.html#46-09", "sub": "4.6 Work Protection"}, {"t": "s", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "4.7", "title": "Latency", "body": "How temporal constraints influence workflows.", "url": "4-7-latency.html"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "47/01", "title": "Design to preserve user momentum.", "body": "Minimize interruptions that break cognitive flow.", "url": "4-7-latency.html#47-01", "sub": "4.7 Latency"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "47/02", "title": "Provide instant acknowledgment of user input.", "body": "Respond perceptually even if processing continues.", "url": "4-7-latency.html#47-02", "sub": "4.7 Latency"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "47/03", "title": "Reduce perceived latency through visible system activity.", "body": "Do not allow silent waiting states.", "url": "4-7-latency.html#47-03", "sub": "4.7 Latency"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "47/04", "title": "Keep users productively occupied during delays.", "body": "Prevent blocking states that halt all interaction.", "url": "4-7-latency.html#47-04", "sub": "4.7 Latency"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "47/05", "title": "Separate initiation from completion when possible.", "body": "Allow background processing without freezing interaction.", "url": "4-7-latency.html#47-05", "sub": "4.7 Latency"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "47/06", "title": "Minimize dependent sequential requests.", "body": "Reduce cumulative delays caused by repeated server interactions.", "url": "4-7-latency.html#47-06", "sub": "4.7 Latency"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "47/07", "title": "Avoid requiring decisions during idle delays.", "body": "Do not compound waiting with cognitive effort.", "url": "4-7-latency.html#47-07", "sub": "4.7 Latency"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "47/08", "title": "Provide truthful and proportional progress feedback.", "body": "Avoid misleading estimates or cosmetic animations.", "url": "4-7-latency.html#47-08", "sub": "4.7 Latency"}, {"t": "d", "c": 4, "ch": "System Behavior & Workflow Logic", "id": "47/09", "title": "Ensure graceful degradation under poor conditions.", "body": "Maintain usability during slow or unstable performance.", "url": "4-7-latency.html#47-09", "sub": "4.7 Latency"}, {"t": "s", "c": 5, "ch": "Visual Communication", "id": "5.1", "title": "Visual Hierarchy", "body": "What the eye sees first.", "url": "5-1-visual-hierarchy.html"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "51/01", "title": "Establish priority perceptually before relying on text.", "body": "Design layouts so importance is understood before labels are processed.", "url": "5-1-visual-hierarchy.html#51-01", "sub": "5.1 Visual Hierarchy"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "51/02", "title": "Differentiate elements by importance.", "body": "Do not assign equal visual weight to unequal information.", "url": "5-1-visual-hierarchy.html#51-02", "sub": "5.1 Visual Hierarchy"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "51/03", "title": "Define hierarchy structurally before styling.", "body": "Use layout, grouping, and scale as primary tools of prioritization.", "url": "5-1-visual-hierarchy.html#51-03", "sub": "5.1 Visual Hierarchy"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "51/04", "title": "Make primary elements immediately recognizable.", "body": "Ensure users can identify focal points without scanning extensively.", "url": "5-1-visual-hierarchy.html#51-04", "sub": "5.1 Visual Hierarchy"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "51/05", "title": "Use contrast to guide attention intentionally.", "body": "Remove decorative contrast that distracts from priority.", "url": "5-1-visual-hierarchy.html#51-05", "sub": "5.1 Visual Hierarchy"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "51/06", "title": "Use whitespace to reinforce grouping and priority.", "body": "Apply spacing deliberately to clarify relationships and emphasis.", "url": "5-1-visual-hierarchy.html#51-06", "sub": "5.1 Visual Hierarchy"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "51/07", "title": "Use typography to reinforce hierarchy, not to create it.", "body": "Ensure structural hierarchy remains intact independent of typographic styling.", "url": "5-1-visual-hierarchy.html#51-07", "sub": "5.1 Visual Hierarchy"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "51/08", "title": "Align hierarchy with user goals.", "body": "Prioritize elements according to user tasks, not internal priorities.", "url": "5-1-visual-hierarchy.html#51-08", "sub": "5.1 Visual Hierarchy"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "51/09", "title": "Maintain consistent hierarchy patterns across screens.", "body": "Keep priority signals consistent between contexts.", "url": "5-1-visual-hierarchy.html#51-09", "sub": "5.1 Visual Hierarchy"}, {"t": "s", "c": 5, "ch": "Visual Communication", "id": "5.2", "title": "Contrast", "body": "What can be distinguished at all.", "url": "5-2-contrast.html"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "52/01", "title": "Ensure adequate contrast for all meaningful distinctions.", "body": "Make important elements visually prominent for immediate perception.", "url": "5-2-contrast.html#52-01", "sub": "5.2 Contrast"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "52/02", "title": "Evaluate contrast relative to surrounding elements.", "body": "Design emphasis based on local visual context, not isolated components.", "url": "5-2-contrast.html#52-02", "sub": "5.2 Contrast"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "52/03", "title": "Use multiple visual channels to establish contrast.", "body": "Reinforce color differences with form, size, placement, or motion.", "url": "5-2-contrast.html#52-03", "sub": "5.2 Contrast"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "52/04", "title": "Meet accessibility thresholds for perceptual distinction.", "body": "Ensure contrast remains usable across varied abilities and conditions.", "url": "5-2-contrast.html#52-04", "sub": "5.2 Contrast"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "52/05", "title": "Calibrate contrast according to consequence.", "body": "Increase visual differentiation proportionally for high-risk states.", "url": "5-2-contrast.html#52-05", "sub": "5.2 Contrast"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "52/06", "title": "Align contrast with established visual hierarchy.", "body": "Do not allow emphasis to conflict with structural priority.", "url": "5-2-contrast.html#52-06", "sub": "5.2 Contrast"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "52/07", "title": "Limit simultaneous high-contrast elements.", "body": "Prevent visual noise by reserving strong emphasis for true priority.", "url": "5-2-contrast.html#52-07", "sub": "5.2 Contrast"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "52/08", "title": "Ensure state-driven contrast changes are predictable.", "body": "Guard against unexpected shifts in emphasis that disrupt understanding.", "url": "5-2-contrast.html#52-08", "sub": "5.2 Contrast"}, {"t": "s", "c": 5, "ch": "Visual Communication", "id": "5.3", "title": "Readability", "body": "How easily content can be consumed.", "url": "5-3-readability.html"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "53/01", "title": "Design text for comprehension, not mere legibility.", "body": "Ensure content can be understood, not just visually decoded.", "url": "5-3-readability.html#53-01", "sub": "5.3 Readability"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "53/02", "title": "Enable orientation through scannable structure.", "body": "Design headings, summaries, and layout to support rapid comprehension.", "url": "5-3-readability.html#53-02", "sub": "5.3 Readability"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "53/03", "title": "Use structural organization to support meaning.", "body": "Apply grouping, hierarchy, and spacing to clarify relationships.", "url": "5-3-readability.html#53-03", "sub": "5.3 Readability"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "53/04", "title": "Eliminate unnecessary cognitive translation.", "body": "Write and structure text so users do not need to reinterpret meaning.", "url": "5-3-readability.html#53-04", "sub": "5.3 Readability"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "53/05", "title": "Maintain consistent terminology and structure.", "body": "Guard against unnecessary variation in labels and phrasing.", "url": "5-3-readability.html#53-05", "sub": "5.3 Readability"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "53/06", "title": "Treat microcopy as functional design.", "body": "Use concise, purposeful language that supports task completion.", "url": "5-3-readability.html#53-06", "sub": "5.3 Readability"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "53/07", "title": "Optimize text density and rhythm for sustained reading.", "body": "Design typography and layout to reduce fatigue over prolonged use.", "url": "5-3-readability.html#53-07", "sub": "5.3 Readability"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "53/08", "title": "Design text to prevent behavioral error.", "body": "Ensure wording clarifies action and consequence to reduce hesitation.", "url": "5-3-readability.html#53-08", "sub": "5.3 Readability"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "53/09", "title": "Support re-entry into content.", "body": "Structure text so users can resume reading without full repetition.", "url": "5-3-readability.html#53-09", "sub": "5.3 Readability"}, {"t": "s", "c": 5, "ch": "Visual Communication", "id": "5.4", "title": "Accessibility", "body": "Whether content can be perceived by all users.", "url": "5-4-accessibility.html"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "54/01", "title": "Design for equal task capability.", "body": "Ensure all users can complete core tasks, not merely access interface elements.", "url": "5-4-accessibility.html#54-01", "sub": "5.4 Accessibility"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "54/02", "title": "Design for human variability as a baseline condition.", "body": "Account for a wide range of sensory, motor, and cognitive differences.", "url": "5-4-accessibility.html#54-02", "sub": "5.4 Accessibility"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "54/03", "title": "Ensure accessible workflows are functionally equivalent.", "body": "Prevent degraded or secondary experiences for alternative access paths.", "url": "5-4-accessibility.html#54-03", "sub": "5.4 Accessibility"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "54/04", "title": "Make state and consequence clearly distinguishable.", "body": "Design perceptible differentiation for actions, options, and outcomes.", "url": "5-4-accessibility.html#54-04", "sub": "5.4 Accessibility"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "54/05", "title": "Do not rely on a single sensory channel.", "body": "Ensure focus, state, and feedback are perceivable across modalities.", "url": "5-4-accessibility.html#54-05", "sub": "5.4 Accessibility"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "54/06", "title": "Provide multimodal interaction paths.", "body": "Support visual, auditory, tactile, and keyboard-based input equivalently.", "url": "5-4-accessibility.html#54-06", "sub": "5.4 Accessibility"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "54/07", "title": "Treat alternative input methods as primary.", "body": "Design keyboard, screen reader, and touch interaction with equal priority.", "url": "5-4-accessibility.html#54-07", "sub": "5.4 Accessibility"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "54/08", "title": "Ensure dynamic and automated content remains accessible.", "body": "Preserve operability and legibility in changing or AI-driven interfaces.", "url": "5-4-accessibility.html#54-08", "sub": "5.4 Accessibility"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "54/09", "title": "Design accessibility for real-world conditions.", "body": "Ensure usability persists under fatigue, distraction, and urgency.", "url": "5-4-accessibility.html#54-09", "sub": "5.4 Accessibility"}, {"t": "s", "c": 5, "ch": "Visual Communication", "id": "5.5", "title": "Information Density", "body": "How much can be held in view.", "url": "5-5-information-density.html"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "55/01", "title": "Calibrate density to support reasoning.", "body": "Prioritize cognitive clarity over visual minimalism.", "url": "5-5-information-density.html#55-01", "sub": "5.5 Information Density"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "55/02", "title": "Do not force users to switch views or context during critical decisions.", "body": "Ensure supporting information needed for essential reasoning is co-present.", "url": "5-5-information-density.html#55-02", "sub": "5.5 Information Density"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "55/03", "title": "Prevent fragmentation of essential information.", "body": "Maintain interdependent content in a single view.", "url": "5-5-information-density.html#55-03", "sub": "5.5 Information Density"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "55/04", "title": "Guard against overcrowding that collapses hierarchy.", "body": "Preserve clear priority signals within dense layouts.", "url": "5-5-information-density.html#55-04", "sub": "5.5 Information Density"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "55/05", "title": "Use structural grouping to manage density.", "body": "Organize information to clarify relationships and reduce perceived clutter.", "url": "5-5-information-density.html#55-05", "sub": "5.5 Information Density"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "55/06", "title": "Use whitespace to structure, not to conceal insufficiency.", "body": "Apply spacing to improve clarity without removing necessary content.", "url": "5-5-information-density.html#55-06", "sub": "5.5 Information Density"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "55/07", "title": "Design to minimize unnecessary scanning.", "body": "Ensure layout and density provide sufficient contextual cues.", "url": "5-5-information-density.html#55-07", "sub": "5.5 Information Density"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "55/08", "title": "Adjust density according to task phase.", "body": "Increase or reduce visible context based on exploration, execution, or review needs.", "url": "5-5-information-density.html#55-08", "sub": "5.5 Information Density"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "55/09", "title": "Scale density to user expertise.", "body": "Provide expanded contextual visibility for experienced users.", "url": "5-5-information-density.html#55-09", "sub": "5.5 Information Density"}, {"t": "s", "c": 5, "ch": "Visual Communication", "id": "5.6", "title": "Color Semantics", "body": "How meaning and state are reinforced.", "url": "5-6-color-semantics.html"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "56/01", "title": "Use color as a semantic signal, not decoration.", "body": "Assign intentional meaning to color and treat it as part of the interface vocabulary.", "url": "5-6-color-semantics.html#56-01", "sub": "5.6 Color Semantics"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "56/02", "title": "Maintain consistent color semantics system-wide.", "body": "Ensure each semantic color carries a single, stable meaning.", "url": "5-6-color-semantics.html#56-02", "sub": "5.6 Color Semantics"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "56/03", "title": "Align color with actual consequence.", "body": "Ensure outcomes match the expectation established by color usage.", "url": "5-6-color-semantics.html#56-03", "sub": "5.6 Color Semantics"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "56/04", "title": "Eliminate misleading or exaggerated color signaling.", "body": "Ensure colors do not overstate importance or certainty.", "url": "5-6-color-semantics.html#56-04", "sub": "5.6 Color Semantics"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "56/05", "title": "Limit the semantic color vocabulary.", "body": "Restrict color meanings to a deliberate, governable set.", "url": "5-6-color-semantics.html#56-05", "sub": "5.6 Color Semantics"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "56/06", "title": "Reinforce semantic color with additional cues.", "body": "Pair color with text, iconography, or structural signals.", "url": "5-6-color-semantics.html#56-06", "sub": "5.6 Color Semantics"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "56/07", "title": "Ensure color semantics remain perceptible across contexts.", "body": "Validate meaning under varied contrast and environmental conditions.", "url": "5-6-color-semantics.html#56-07", "sub": "5.6 Color Semantics"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "56/08", "title": "Scale color intensity according to consequence.", "body": "Use stronger emphasis for higher-risk states.", "url": "5-6-color-semantics.html#56-08", "sub": "5.6 Color Semantics"}, {"t": "s", "c": 5, "ch": "Visual Communication", "id": "5.7", "title": "Functional Aesthetics", "body": "What drives emotional and credibility dimensions.", "url": "5-7-functional-aesthetics.html"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "57/01", "title": "Ensure aesthetics reinforce functional clarity.", "body": "Do not introduce visual elements that distract from purpose.", "url": "5-7-functional-aesthetics.html#57-01", "sub": "5.7 Functional Aesthetics"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "57/02", "title": "Prioritize clarity over visual expressiveness.", "body": "Design visuals that recede during task execution.", "url": "5-7-functional-aesthetics.html#57-02", "sub": "5.7 Functional Aesthetics"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "57/03", "title": "Align visual styling with hierarchy and affordance.", "body": "Ensure style strengthens structural signals.", "url": "5-7-functional-aesthetics.html#57-03", "sub": "5.7 Functional Aesthetics"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "57/04", "title": "Apply visual restraint deliberately.", "body": "Limit emphasis to elements that require attention.", "url": "5-7-functional-aesthetics.html#57-04", "sub": "5.7 Functional Aesthetics"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "57/05", "title": "Eliminate unnecessary visual noise.", "body": "Remove decorative elements that increase cognitive load.", "url": "5-7-functional-aesthetics.html#57-05", "sub": "5.7 Functional Aesthetics"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "57/06", "title": "Design for immediate visual credibility.", "body": "Ensure visual coherence communicates reliability at first glance.", "url": "5-7-functional-aesthetics.html#57-06", "sub": "5.7 Functional Aesthetics"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "57/07", "title": "Maintain visual consistency across the system.", "body": "Do not allow stylistic variation that signals instability.", "url": "5-7-functional-aesthetics.html#57-07", "sub": "5.7 Functional Aesthetics"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "57/08", "title": "Increase visual discipline as system complexity grows.", "body": "Preserve clarity and coherence in large-scale interfaces.", "url": "5-7-functional-aesthetics.html#57-08", "sub": "5.7 Functional Aesthetics"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "57/09", "title": "Favor durable visual systems over trends.", "body": "Prioritize long-term credibility over short-term novelty.", "url": "5-7-functional-aesthetics.html#57-09", "sub": "5.7 Functional Aesthetics"}, {"t": "s", "c": 5, "ch": "Visual Communication", "id": "5.8", "title": "Motion", "body": "How movement communicates change.", "url": "5-8-motion.html"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "58/01", "title": "Use motion only to explain change.", "body": "Animate state, position, or hierarchy changes, not static content.", "url": "5-8-motion.html#58-01", "sub": "5.8 Motion"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "58/02", "title": "Show origin and destination.", "body": "Let motion connect where an element was to where it is.", "url": "5-8-motion.html#58-02", "sub": "5.8 Motion"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "58/03", "title": "Keep motion brief.", "body": "Prevent animation from delaying task progress.", "url": "5-8-motion.html#58-03", "sub": "5.8 Motion"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "58/04", "title": "Never block input with motion.", "body": "Allow users to act while transitions run.", "url": "5-8-motion.html#58-04", "sub": "5.8 Motion"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "58/05", "title": "Use physically plausible easing.", "body": "Make movement accelerate and settle in ways users can follow.", "url": "5-8-motion.html#58-05", "sub": "5.8 Motion"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "58/06", "title": "Keep a consistent motion vocabulary.", "body": "Use the same motion for the same kind of change everywhere.", "url": "5-8-motion.html#58-06", "sub": "5.8 Motion"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "58/07", "title": "Respect reduced-motion preferences.", "body": "Provide equivalent non-animated feedback when motion is reduced or off.", "url": "5-8-motion.html#58-07", "sub": "5.8 Motion"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "58/08", "title": "Keep motion subordinate to the task.", "body": "Avoid movement that draws attention away from the primary activity.", "url": "5-8-motion.html#58-08", "sub": "5.8 Motion"}, {"t": "d", "c": 5, "ch": "Visual Communication", "id": "58/09", "title": "Do not encode meaning in motion alone.", "body": "Pair motion with a static cue that remains after it ends.", "url": "5-8-motion.html#58-09", "sub": "5.8 Motion"}, {"t": "s", "c": 6, "ch": "Consistency & Coherence", "id": "6.1", "title": "Consistency", "body": "How to preserve stable meaning over time.", "url": "6-1-consistency.html"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "61/01", "title": "Preserve learned behavior across contexts.", "body": "Ensure interaction patterns transfer without reinterpretation.", "url": "6-1-consistency.html#61-01", "sub": "6.1 Consistency"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "61/02", "title": "Prioritize behavioral consistency over visual uniformity.", "body": "Do not allow identical appearances to mask different behaviors.", "url": "6-1-consistency.html#61-02", "sub": "6.1 Consistency"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "61/03", "title": "Eliminate unnecessary behavioral variation.", "body": "Prevent forcing users to re-evaluate familiar patterns.", "url": "6-1-consistency.html#61-03", "sub": "6.1 Consistency"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "61/04", "title": "Design for predictable interaction outcomes.", "body": "Ensure similar actions yield similar results.", "url": "6-1-consistency.html#61-04", "sub": "6.1 Consistency"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "61/05", "title": "Make exceptions explicit.", "body": "Indicate clearly when standard patterns do not apply.", "url": "6-1-consistency.html#61-05", "sub": "6.1 Consistency"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "61/06", "title": "Introduce changes transparently and deliberately.", "body": "Communicate and justify meaningful shifts in behavior.", "url": "6-1-consistency.html#61-06", "sub": "6.1 Consistency"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "61/07", "title": "Maintain consistency across sessions and versions.", "body": "Preserve interaction logic for returning users.", "url": "6-1-consistency.html#61-07", "sub": "6.1 Consistency"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "61/08", "title": "Govern consistency at system scale.", "body": "Prevent isolated design decisions that conflict with global patterns.", "url": "6-1-consistency.html#61-08", "sub": "6.1 Consistency"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "61/09", "title": "Preserve core interaction invariants in adaptive systems.", "body": "Ensure personalization does not alter fundamental rules.", "url": "6-1-consistency.html#61-09", "sub": "6.1 Consistency"}, {"t": "s", "c": 6, "ch": "Consistency & Coherence", "id": "6.2", "title": "Conventions", "body": "How systems align with external user expectations.", "url": "6-2-conventions.html"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "62/01", "title": "Align with established platform conventions.", "body": "Design in accordance with shared behavioral expectations.", "url": "6-2-conventions.html#62-01", "sub": "6.2 Conventions"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "62/02", "title": "Leverage familiar interaction patterns.", "body": "Use conventional behaviors to reduce onboarding friction.", "url": "6-2-conventions.html#62-02", "sub": "6.2 Conventions"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "62/03", "title": "Ensure behavioral fidelity to conventional forms.", "body": "Do not replicate familiar visuals without matching expected behavior.", "url": "6-2-conventions.html#62-03", "sub": "6.2 Conventions"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "62/04", "title": "Apply conventions consistently.", "body": "Do not mix conventional and non-conventional patterns without clear boundaries.", "url": "6-2-conventions.html#62-04", "sub": "6.2 Conventions"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "62/05", "title": "Deviate from conventions only with clear benefit.", "body": "Ensure convention departures improve function meaningfully.", "url": "6-2-conventions.html#62-05", "sub": "6.2 Conventions"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "62/06", "title": "Signal deviations clearly and confine them locally.", "body": "Make unconventional behavior obvious and contained.", "url": "6-2-conventions.html#62-06", "sub": "6.2 Conventions"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "62/07", "title": "Prioritize convention adherence in primary workflows.", "body": "Protect high-frequency tasks from unnecessary novelty.", "url": "6-2-conventions.html#62-07", "sub": "6.2 Conventions"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "62/08", "title": "Use conventions to maintain cross-modality consistency.", "body": "Ensure conventional behavior extends to all supported inputs.", "url": "6-2-conventions.html#62-08", "sub": "6.2 Conventions"}, {"t": "s", "c": 6, "ch": "Consistency & Coherence", "id": "6.3", "title": "Patterns", "body": "How to scale behavior without fragmentation.", "url": "6-3-patterns.html"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "63/01", "title": "Use patterns to preserve learned behavior.", "body": "Design recurring structures to reduce reinterpretation.", "url": "6-3-patterns.html#63-01", "sub": "6.3 Patterns"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "63/02", "title": "Ensure behavioral consistency within patterns.", "body": "Do not reuse visuals without preserving interaction logic.", "url": "6-3-patterns.html#63-02", "sub": "6.3 Patterns"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "63/03", "title": "Prefer reuse over unnecessary invention.", "body": "Introduce new patterns only when existing ones cannot serve the need.", "url": "6-3-patterns.html#63-03", "sub": "6.3 Patterns"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "63/04", "title": "Apply patterns comprehensively across contexts.", "body": "Prevent fragmenting pattern logic within the system.", "url": "6-3-patterns.html#63-04", "sub": "6.3 Patterns"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "63/05", "title": "Design patterns for cross-context scalability.", "body": "Ensure recurring structures function reliably in varied situations.", "url": "6-3-patterns.html#63-05", "sub": "6.3 Patterns"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "63/06", "title": "Extend patterns incrementally during growth.", "body": "Add capability without breaking established logic.", "url": "6-3-patterns.html#63-06", "sub": "6.3 Patterns"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "63/07", "title": "Limit and signal deviations from established patterns.", "body": "Ensure exceptions are intentional and explicit.", "url": "6-3-patterns.html#63-07", "sub": "6.3 Patterns"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "63/08", "title": "Evolve patterns transparently.", "body": "Communicate meaningful pattern changes to prevent forced relearning.", "url": "6-3-patterns.html#63-08", "sub": "6.3 Patterns"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "63/09", "title": "Formalize patterns as shared system contracts.", "body": "Maintain documentation to preserve coherence across teams.", "url": "6-3-patterns.html#63-09", "sub": "6.3 Patterns"}, {"t": "s", "c": 6, "ch": "Consistency & Coherence", "id": "6.4", "title": "Design System Integrity", "body": "How systems maintain coherence as they evolve.", "url": "6-4-design-system-integrity.html"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "64/01", "title": "Prioritize systemic coherence over breadth.", "body": "Maintain internal consistency before expanding scope.", "url": "6-4-design-system-integrity.html#64-01", "sub": "6.4 Design System Integrity"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "64/02", "title": "Define and enforce governing principles.", "body": "Anchor components in stable rules, not isolated artifacts.", "url": "6-4-design-system-integrity.html#64-02", "sub": "6.4 Design System Integrity"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "64/03", "title": "Make system standards enforceable.", "body": "Ensure guidelines translate into constraints in design and code.", "url": "6-4-design-system-integrity.html#64-03", "sub": "6.4 Design System Integrity"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "64/04", "title": "Enable safe extension of the system.", "body": "Provide structured paths to add new patterns without fragmentation.", "url": "6-4-design-system-integrity.html#64-04", "sub": "6.4 Design System Integrity"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "64/05", "title": "Establish clear and efficient governance mechanisms.", "body": "Balance oversight with practicality for contributors.", "url": "6-4-design-system-integrity.html#64-05", "sub": "6.4 Design System Integrity"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "64/06", "title": "Manage and communicate system changes transparently.", "body": "Ensure updates are deliberate and documented.", "url": "6-4-design-system-integrity.html#64-06", "sub": "6.4 Design System Integrity"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "64/07", "title": "Design systems to withstand rapid growth and deadlines.", "body": "Ensure standards remain intact under institutional pressure.", "url": "6-4-design-system-integrity.html#64-07", "sub": "6.4 Design System Integrity"}, {"t": "d", "c": 6, "ch": "Consistency & Coherence", "id": "64/08", "title": "Monitor and address accumulating design debt.", "body": "Refactor inconsistencies regularly before fragmentation accelerates.", "url": "6-4-design-system-integrity.html#64-08", "sub": "6.4 Design System Integrity"}, {"t": "s", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "7.1", "title": "Consent & Control", "body": "Who decides and when.", "url": "7-1-consent-and-control.html"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "71/01", "title": "Design consent as a continuous capability.", "body": "Allow users to review, modify, and revoke consent at any time.", "url": "7-1-consent-and-control.html#71-01", "sub": "7.1 Consent & Control"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "71/02", "title": "Ensure user controls produce actual system change.", "body": "Do not offer settings that lack meaningful impact.", "url": "7-1-consent-and-control.html#71-02", "sub": "7.1 Consent & Control"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "71/03", "title": "Make the scope of control explicit.", "body": "Define clearly what actions or data are governed by consent.", "url": "7-1-consent-and-control.html#71-03", "sub": "7.1 Consent & Control"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "71/04", "title": "Enable simple and penalty-free withdrawal.", "body": "Ensure users can revoke participation without harm.", "url": "7-1-consent-and-control.html#71-04", "sub": "7.1 Consent & Control"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "71/05", "title": "Keep automated processes interruptible.", "body": "Preserve user authority over automated actions.", "url": "7-1-consent-and-control.html#71-05", "sub": "7.1 Consent & Control"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "71/06", "title": "Scale control mechanisms with risk levels.", "body": "Increase oversight and safeguards for high-consequence actions.", "url": "7-1-consent-and-control.html#71-06", "sub": "7.1 Consent & Control"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "71/07", "title": "Do not allow implicit or overreaching defaults.", "body": "Require explicit user acknowledgment for consequential actions.", "url": "7-1-consent-and-control.html#71-07", "sub": "7.1 Consent & Control"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "71/08", "title": "Preserve consent integrity across updates.", "body": "Do not broaden authority without renewed permission.", "url": "7-1-consent-and-control.html#71-08", "sub": "7.1 Consent & Control"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "71/09", "title": "Enforce consent consistently in system behavior.", "body": "Ensure actions align with stated permissions at all times.", "url": "7-1-consent-and-control.html#71-09", "sub": "7.1 Consent & Control"}, {"t": "s", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "7.2", "title": "Transparency", "body": "Why systems behave as they do.", "url": "7-2-transparency.html"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "72/01", "title": "Design transparency to support trust and intervention.", "body": "Ensure explanations empower user correction, not passive observation.", "url": "7-2-transparency.html#72-01", "sub": "7.2 Transparency"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "72/02", "title": "Provide decision-relevant clarity.", "body": "Deliver explanations sufficient for informed action without overwhelming detail.", "url": "7-2-transparency.html#72-02", "sub": "7.2 Transparency"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "72/03", "title": "Expose causal relationships.", "body": "Make inputs, triggers, and outcomes traceable.", "url": "7-2-transparency.html#72-03", "sub": "7.2 Transparency"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "72/04", "title": "Communicate uncertainty proportionally.", "body": "Align confidence indicators with actual reliability.", "url": "7-2-transparency.html#72-04", "sub": "7.2 Transparency"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "72/05", "title": "Increase explanatory depth for high-risk outcomes.", "body": "Provide greater insight where stakes are higher.", "url": "7-2-transparency.html#72-05", "sub": "7.2 Transparency"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "72/06", "title": "Enable correction mechanisms alongside explanation.", "body": "Pair visibility with meaningful user action.", "url": "7-2-transparency.html#72-06", "sub": "7.2 Transparency"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "72/07", "title": "Ensure explanatory accuracy with simplicity.", "body": "Simplify without misrepresenting system behavior.", "url": "7-2-transparency.html#72-07", "sub": "7.2 Transparency"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "72/08", "title": "Deliver explanations at the point of impact.", "body": "Provide visibility before or while a consequence unfolds, not after.", "url": "7-2-transparency.html#72-08", "sub": "7.2 Transparency"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "72/09", "title": "Curate explanations for relevance.", "body": "Do not overwhelm users with unnecessary technical detail.", "url": "7-2-transparency.html#72-09", "sub": "7.2 Transparency"}, {"t": "s", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "7.3", "title": "Error Communication", "body": "How systems communicate when things go wrong.", "url": "7-3-error-communication.html"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "73/01", "title": "Frame errors as system conditions.", "body": "Never attribute failures to users.", "url": "7-3-error-communication.html#73-01", "sub": "7.3 Error Communication"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "73/02", "title": "Use system-owned language in error messaging.", "body": "Communicate accountability clearly and respectfully.", "url": "7-3-error-communication.html#73-02", "sub": "7.3 Error Communication"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "73/03", "title": "Maintain calm, respectful tone.", "body": "Do not use language that induces stress or defensiveness.", "url": "7-3-error-communication.html#73-03", "sub": "7.3 Error Communication"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "73/04", "title": "Provide clear explanation of failures.", "body": "Describe what occurred in plain language.", "url": "7-3-error-communication.html#73-04", "sub": "7.3 Error Communication"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "73/05", "title": "Localize and specify error context.", "body": "Identify where and why issues occurred.", "url": "7-3-error-communication.html#73-05", "sub": "7.3 Error Communication"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "73/06", "title": "Include actionable recovery guidance.", "body": "Provide clear instructions for resolution and continuation.", "url": "7-3-error-communication.html#73-06", "sub": "7.3 Error Communication"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "73/07", "title": "Calibrate language to consequence.", "body": "Match urgency and emphasis to actual impact.", "url": "7-3-error-communication.html#73-07", "sub": "7.3 Error Communication"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "73/08", "title": "Translate technical causes into user-relevant language.", "body": "Do not expose internal system terminology unnecessarily.", "url": "7-3-error-communication.html#73-08", "sub": "7.3 Error Communication"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "73/09", "title": "Protect user confidence after failure.", "body": "Ensure messaging supports continued engagement.", "url": "7-3-error-communication.html#73-09", "sub": "7.3 Error Communication"}, {"t": "s", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "7.4", "title": "Data Integrity", "body": "Whether data can be trusted.", "url": "7-4-data-integrity.html"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "74/01", "title": "Design for temporal data correctness.", "body": "Ensure information remains accurate across time and state changes.", "url": "7-4-data-integrity.html#74-01", "sub": "7.4 Data Integrity"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "74/02", "title": "Protect primary source data.", "body": "Prevent silent overwriting of original records by derived values.", "url": "7-4-data-integrity.html#74-02", "sub": "7.4 Data Integrity"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "74/03", "title": "Safeguard completeness and scope.", "body": "Detect and prevent duplication, omission, or misapplication of data.", "url": "7-4-data-integrity.html#74-03", "sub": "7.4 Data Integrity"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "74/04", "title": "Ensure atomic or reversible state changes.", "body": "Do not expose users to unstable intermediate states.", "url": "7-4-data-integrity.html#74-04", "sub": "7.4 Data Integrity"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "74/05", "title": "Protect data during partial failures.", "body": "Design systems to maintain correctness through retries and interruptions.", "url": "7-4-data-integrity.html#74-05", "sub": "7.4 Data Integrity"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "74/06", "title": "Enforce integrity in automated processes.", "body": "Ensure scale and automation preserve correctness and reliability.", "url": "7-4-data-integrity.html#74-06", "sub": "7.4 Data Integrity"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "74/07", "title": "Provide mechanisms for data verification.", "body": "Allow users to inspect and confirm accuracy.", "url": "7-4-data-integrity.html#74-07", "sub": "7.4 Data Integrity"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "74/08", "title": "Detect and remediate accumulating inconsistencies.", "body": "Monitor for cascading data errors proactively.", "url": "7-4-data-integrity.html#74-08", "sub": "7.4 Data Integrity"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "74/09", "title": "Design integrity to operate without constant oversight.", "body": "Ensure correctness persists without manual monitoring.", "url": "7-4-data-integrity.html#74-09", "sub": "7.4 Data Integrity"}, {"t": "s", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "7.5", "title": "Privacy", "body": "What happens to personal information.", "url": "7-5-privacy.html"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "75/01", "title": "Collect the minimum.", "body": "Request only the personal information the stated purpose requires.", "url": "7-5-privacy.html#75-01", "sub": "7.5 Privacy"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "75/02", "title": "State purpose at collection.", "body": "Explain why information is needed where and when it is requested.", "url": "7-5-privacy.html#75-02", "sub": "7.5 Privacy"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "75/03", "title": "Default to privacy.", "body": "Set the most protective option as the default.", "url": "7-5-privacy.html#75-03", "sub": "7.5 Privacy"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "75/04", "title": "Make held data visible.", "body": "Let users see all personal information the system holds about them.", "url": "7-5-privacy.html#75-04", "sub": "7.5 Privacy"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "75/05", "title": "Enable correction, export, and deletion.", "body": "Provide direct controls without requiring support contact.", "url": "7-5-privacy.html#75-05", "sub": "7.5 Privacy"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "75/06", "title": "Require specific consent for sharing.", "body": "Do not share personal information with third parties under general or implied consent.", "url": "7-5-privacy.html#75-06", "sub": "7.5 Privacy"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "75/07", "title": "Limit and state retention.", "body": "Keep personal information only as long as stated, then remove it.", "url": "7-5-privacy.html#75-07", "sub": "7.5 Privacy"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "75/08", "title": "Place privacy controls in context.", "body": "Offer privacy choices where the related data is used.", "url": "7-5-privacy.html#75-08", "sub": "7.5 Privacy"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "75/09", "title": "Preserve privacy choices.", "body": "Ensure settings persist across sessions, devices, and updates.", "url": "7-5-privacy.html#75-09", "sub": "7.5 Privacy"}, {"t": "s", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "7.6", "title": "Non-Manipulation", "body": "How the system influences user choices.", "url": "7-6-non-manipulation.html"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "76/01", "title": "Influence only transparently.", "body": "Use persuasion users could recognize and endorse.", "url": "7-6-non-manipulation.html#76-01", "sub": "7.6 Non-Manipulation"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "76/02", "title": "Make exit as easy as entry.", "body": "Provide cancellation, unsubscribing, and deletion with no more steps than signing up.", "url": "7-6-non-manipulation.html#76-02", "sub": "7.6 Non-Manipulation"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "76/03", "title": "Disclose costs before commitment.", "body": "Show full price, recurring charges, and conditions before users agree.", "url": "7-6-non-manipulation.html#76-03", "sub": "7.6 Non-Manipulation"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "76/04", "title": "Use only true urgency and scarcity.", "body": "Do not display timers, stock levels, or demand signals that are not real.", "url": "7-6-non-manipulation.html#76-04", "sub": "7.6 Non-Manipulation"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "76/05", "title": "Do not shame refusal.", "body": "Phrase declining options neutrally.", "url": "7-6-non-manipulation.html#76-05", "sub": "7.6 Non-Manipulation"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "76/06", "title": "Give equal visibility to all options.", "body": "Do not hide or de-emphasize choices that work against the system’s interest.", "url": "7-6-non-manipulation.html#76-06", "sub": "7.6 Non-Manipulation"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "76/07", "title": "Obtain consent explicitly.", "body": "Do not pre-check, bundle, or hide consent choices.", "url": "7-6-non-manipulation.html#76-07", "sub": "7.6 Non-Manipulation"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "76/08", "title": "Do not exploit habit.", "body": "Avoid moving or restyling controls so that routine actions trigger unintended results.", "url": "7-6-non-manipulation.html#76-08", "sub": "7.6 Non-Manipulation"}, {"t": "d", "c": 7, "ch": "Trust, Safety & Responsibility", "id": "76/09", "title": "Honor users’ limits.", "body": "Do not let engagement features override time, spending, or notification limits users set.", "url": "7-6-non-manipulation.html#76-09", "sub": "7.6 Non-Manipulation"}, {"t": "s", "c": 8, "ch": "Adaptation & Evolution", "id": "8.1", "title": "Continuity", "body": "How understanding is preserved across updates.", "url": "8-1-continuity.html"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "81/01", "title": "Protect accumulated user investment during change.", "body": "Ensure updates respect time, effort, and acquired skill.", "url": "8-1-continuity.html#81-01", "sub": "8.1 Continuity"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "81/02", "title": "Preserve work, system state, and conceptual clarity across versions.", "body": "Maintain continuity beyond visual appearance.", "url": "8-1-continuity.html#81-02", "sub": "8.1 Continuity"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "81/03", "title": "Maintain conceptual stability across updates.", "body": "Prevent breaking established reasoning patterns without explicit transition.", "url": "8-1-continuity.html#81-03", "sub": "8.1 Continuity"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "81/04", "title": "Introduce new capability as extension, not replacement.", "body": "Ensure growth expands functionality without invalidating prior learning.", "url": "8-1-continuity.html#81-04", "sub": "8.1 Continuity"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "81/05", "title": "Maintain usability of historical artifacts.", "body": "Prevent degradation of previously created work.", "url": "8-1-continuity.html#81-05", "sub": "8.1 Continuity"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "81/06", "title": "Favor backward compatibility over disruptive novelty.", "body": "Preserve stable interaction contracts whenever possible.", "url": "8-1-continuity.html#81-06", "sub": "8.1 Continuity"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "81/07", "title": "Communicate changes transparently.", "body": "Make updates and their rationale clearly understandable.", "url": "8-1-continuity.html#81-07", "sub": "8.1 Continuity"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "81/08", "title": "Design migrations to be controlled and reversible.", "body": "Allow safe fallback paths during transitions.", "url": "8-1-continuity.html#81-08", "sub": "8.1 Continuity"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "81/09", "title": "Reinforce trust through historical respect.", "body": "Demonstrate reliability by preserving user history over time.", "url": "8-1-continuity.html#81-09", "sub": "8.1 Continuity"}, {"t": "s", "c": 8, "ch": "Adaptation & Evolution", "id": "8.2", "title": "Scalability", "body": "Whether patterns survive growth.", "url": "8-2-scalability.html"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "82/01", "title": "Design scalability for cognitive clarity.", "body": "Ensure meaning and usability survive growth, not just system performance.", "url": "8-2-scalability.html#82-01", "sub": "8.2 Scalability"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "82/02", "title": "Plan for scale from the beginning.", "body": "Build interaction and information models that anticipate growth.", "url": "8-2-scalability.html#82-02", "sub": "8.2 Scalability"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "82/03", "title": "Ensure interaction logic remains stable at larger volumes.", "body": "Do not allow models that collapse under increased data or complexity.", "url": "8-2-scalability.html#82-03", "sub": "8.2 Scalability"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "82/04", "title": "Introduce layered structure as scale increases.", "body": "Use hierarchy and categorization to prevent fragmentation.", "url": "8-2-scalability.html#82-04", "sub": "8.2 Scalability"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "82/05", "title": "Strengthen wayfinding mechanisms as content grows.", "body": "Expand filtering and navigation tools as complexity rises.", "url": "8-2-scalability.html#82-05", "sub": "8.2 Scalability"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "82/06", "title": "Adjust density intelligently as volume grows.", "body": "Increase grouping and structural cues to prevent visual clutter.", "url": "8-2-scalability.html#82-06", "sub": "8.2 Scalability"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "82/07", "title": "Protect efficiency of high-frequency tasks.", "body": "Prevent scale from degrading routine interaction speed.", "url": "8-2-scalability.html#82-07", "sub": "8.2 Scalability"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "82/08", "title": "Leverage defaults and automation to reduce scale burden.", "body": "Minimize manual decision-making as volume increases.", "url": "8-2-scalability.html#82-08", "sub": "8.2 Scalability"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "82/09", "title": "Preserve conceptual continuity during growth.", "body": "Ensure scaling expands existing logic rather than replacing it.", "url": "8-2-scalability.html#82-09", "sub": "8.2 Scalability"}, {"t": "s", "c": 8, "ch": "Adaptation & Evolution", "id": "8.3", "title": "Observability", "body": "How user behavior is measured.", "url": "8-3-observability.html"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "83/01", "title": "Center observability on user outcomes.", "body": "Measure real interaction behavior, not isolated system metrics.", "url": "8-3-observability.html#83-01", "sub": "8.3 Observability"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "83/02", "title": "Track outcome-level indicators.", "body": "Prioritize measures of success, failure, and completion over raw activity counts.", "url": "8-3-observability.html#83-02", "sub": "8.3 Observability"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "83/03", "title": "Design metrics to inform intervention.", "body": "Ensure observed signals can drive concrete design or operational decisions.", "url": "8-3-observability.html#83-03", "sub": "8.3 Observability"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "83/04", "title": "Provide real-time or near real-time feedback loops.", "body": "Deliver insights early enough to influence action.", "url": "8-3-observability.html#83-04", "sub": "8.3 Observability"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "83/05", "title": "Maintain end-to-end workflow visibility.", "body": "Observe complete task flows, not isolated steps.", "url": "8-3-observability.html#83-05", "sub": "8.3 Observability"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "83/06", "title": "Enable root-cause traceability.", "body": "Ensure failures can be connected to triggering events or states.", "url": "8-3-observability.html#83-06", "sub": "8.3 Observability"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "83/07", "title": "Increase monitoring depth alongside automation.", "body": "Expand visibility as systems become more autonomous.", "url": "8-3-observability.html#83-07", "sub": "8.3 Observability"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "83/08", "title": "Scale observability mechanisms as the system grows.", "body": "Ensure insight depth matches system complexity.", "url": "8-3-observability.html#83-08", "sub": "8.3 Observability"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "83/09", "title": "Implement proactive detection mechanisms.", "body": "Do not rely on user complaints for problem detection.", "url": "8-3-observability.html#83-09", "sub": "8.3 Observability"}, {"t": "s", "c": 8, "ch": "Adaptation & Evolution", "id": "8.4", "title": "Validation", "body": "How correctness is maintained over time.", "url": "8-4-validation.html"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "84/01", "title": "Design validation as a continuous process.", "body": "Reassess system correctness as conditions evolve.", "url": "8-4-validation.html#84-01", "sub": "8.4 Validation"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "84/02", "title": "Explicitly test underlying assumptions.", "body": "Ground decisions in observed behavior, not belief.", "url": "8-4-validation.html#84-02", "sub": "8.4 Validation"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "84/03", "title": "Evaluate success by measurable outcomes.", "body": "Judge effectiveness based on real-world results.", "url": "8-4-validation.html#84-03", "sub": "8.4 Validation"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "84/04", "title": "Monitor for contextual and behavioral drift.", "body": "Expect change and track its impact proactively.", "url": "8-4-validation.html#84-04", "sub": "8.4 Validation"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "84/05", "title": "Predefine failure indicators.", "body": "Establish clear criteria that signal when correction is required.", "url": "8-4-validation.html#84-05", "sub": "8.4 Validation"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "84/06", "title": "Detect and respond to issues early.", "body": "Shorten feedback loops to reduce correction cost.", "url": "8-4-validation.html#84-06", "sub": "8.4 Validation"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "84/07", "title": "Treat disconfirmation as progress.", "body": "Incorporate negative findings into improvement cycles.", "url": "8-4-validation.html#84-07", "sub": "8.4 Validation"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "84/08", "title": "Use validation to guide adaptation.", "body": "Prioritize course correction over defending prior choices.", "url": "8-4-validation.html#84-08", "sub": "8.4 Validation"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "84/09", "title": "Increase validation rigor in automated systems.", "body": "Strengthen feedback mechanisms as speed and scale grow.", "url": "8-4-validation.html#84-09", "sub": "8.4 Validation"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "84/10", "title": "Validate under stress and atypical conditions.", "body": "Ensure correctness holds beyond ideal scenarios.", "url": "8-4-validation.html#84-10", "sub": "8.4 Validation"}, {"t": "s", "c": 8, "ch": "Adaptation & Evolution", "id": "8.5", "title": "Personalization", "body": "How the system adapts to the individual.", "url": "8-5-personalization.html"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "85/01", "title": "Personalize for user goals.", "body": "Adapt what helps the user’s task, not only what increases engagement.", "url": "8-5-personalization.html#85-01", "sub": "8.5 Personalization"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "85/02", "title": "Mark adapted content.", "body": "Indicate which elements are personalized.", "url": "8-5-personalization.html#85-02", "sub": "8.5 Personalization"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "85/03", "title": "Explain personalization.", "body": "Show the reason an item was adapted or recommended.", "url": "8-5-personalization.html#85-03", "sub": "8.5 Personalization"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "85/04", "title": "Let users tune adaptation.", "body": "Provide controls to adjust or turn off personalization.", "url": "8-5-personalization.html#85-04", "sub": "8.5 Personalization"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "85/05", "title": "Keep the core model shared.", "body": "Do not personalize structure or interaction rules that all users rely on.", "url": "8-5-personalization.html#85-05", "sub": "8.5 Personalization"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "85/06", "title": "Adapt gradually.", "body": "Avoid abrupt changes that invalidate what users have learned.", "url": "8-5-personalization.html#85-06", "sub": "8.5 Personalization"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "85/07", "title": "Provide a way back to default.", "body": "Let users reset personalization at any time.", "url": "8-5-personalization.html#85-07", "sub": "8.5 Personalization"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "85/08", "title": "Preserve breadth of discovery.", "body": "Prevent personalization from hiding content users have not yet encountered.", "url": "8-5-personalization.html#85-08", "sub": "8.5 Personalization"}, {"t": "d", "c": 8, "ch": "Adaptation & Evolution", "id": "85/09", "title": "Rank explicit settings above inference.", "body": "Let stated preferences override inferred ones.", "url": "8-5-personalization.html#85-09", "sub": "8.5 Personalization"}, {"t": "s", "c": 9, "ch": "AI-Mediated Interaction", "id": "9.1", "title": "Human Oversight", "body": "Who remains accountable.", "url": "9-1-human-oversight.html"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "91/01", "title": "Preserve human accountability in automated systems.", "body": "Ensure responsibility remains clearly assigned to a human actor.", "url": "9-1-human-oversight.html#91-01", "sub": "9.1 Human Oversight"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "91/02", "title": "Define oversight roles explicitly.", "body": "Clarify who is responsible for monitoring and intervention.", "url": "9-1-human-oversight.html#91-02", "sub": "9.1 Human Oversight"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "91/03", "title": "Provide sufficient visibility into system behavior.", "body": "Expose actions, state, and rationale necessary for oversight.", "url": "9-1-human-oversight.html#91-03", "sub": "9.1 Human Oversight"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "91/04", "title": "Align oversight authority with risk and consequence.", "body": "Grant decision power proportionate to accountability.", "url": "9-1-human-oversight.html#91-04", "sub": "9.1 Human Oversight"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "91/05", "title": "Enable real-time intervention capabilities.", "body": "Ensure humans can meaningfully influence outcomes before harm occurs.", "url": "9-1-human-oversight.html#91-05", "sub": "9.1 Human Oversight"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "91/06", "title": "Design for safe, preemptive intervention.", "body": "Support interruption and correction during execution.", "url": "9-1-human-oversight.html#91-06", "sub": "9.1 Human Oversight"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "91/07", "title": "Maintain interruptibility of automated processes.", "body": "Prevent irreversible actions without human confirmation.", "url": "9-1-human-oversight.html#91-07", "sub": "9.1 Human Oversight"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "91/08", "title": "Calibrate oversight rigor to consequence severity.", "body": "Increase human involvement for high-risk scenarios.", "url": "9-1-human-oversight.html#91-08", "sub": "9.1 Human Oversight"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "91/09", "title": "Ensure traceability of automated decisions.", "body": "Maintain logs and records to support review and accountability.", "url": "9-1-human-oversight.html#91-09", "sub": "9.1 Human Oversight"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "91/10", "title": "Design systems to enable meaningful override.", "body": "Support human disagreement and correction of automated outcomes.", "url": "9-1-human-oversight.html#91-10", "sub": "9.1 Human Oversight"}, {"t": "s", "c": 9, "ch": "AI-Mediated Interaction", "id": "9.2", "title": "Learning Consent", "body": "What a system may learn and apply.", "url": "9-2-learning-consent.html"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "92/01", "title": "Treat learning from users as delegated authority.", "body": "Require explicit consent before user data shapes system behavior.", "url": "9-2-learning-consent.html#92-01", "sub": "9.2 Learning Consent"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "92/02", "title": "Make learning consent clear and comprehensible.", "body": "Explain what is learned, from which data, and for what purpose.", "url": "9-2-learning-consent.html#92-02", "sub": "9.2 Learning Consent"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "92/03", "title": "Expose the scope of learning.", "body": "Indicate which data, features, and time periods learning covers.", "url": "9-2-learning-consent.html#92-03", "sub": "9.2 Learning Consent"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "92/04", "title": "Scale consent rigor with sensitivity.", "body": "Require stronger acknowledgment for learning from personal or high-impact data.", "url": "9-2-learning-consent.html#92-04", "sub": "9.2 Learning Consent"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "92/05", "title": "Separate learning from acting.", "body": "Require distinct authorization before learned behavior drives consequential actions.", "url": "9-2-learning-consent.html#92-05", "sub": "9.2 Learning Consent"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "92/06", "title": "Make learned behavior inspectable and correctable.", "body": "Allow users to see and edit what the system has learned about them.", "url": "9-2-learning-consent.html#92-06", "sub": "9.2 Learning Consent"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "92/07", "title": "Ensure learning can be withdrawn.", "body": "Remove learned data and behavior when users revoke consent, without loss of their work.", "url": "9-2-learning-consent.html#92-07", "sub": "9.2 Learning Consent"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "92/08", "title": "Prevent silent scope expansion.", "body": "Require renewed consent if learning extends to new data or purposes.", "url": "9-2-learning-consent.html#92-08", "sub": "9.2 Learning Consent"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "92/09", "title": "Do not treat inference as instruction.", "body": "Keep inferred preferences subordinate to what users explicitly state.", "url": "9-2-learning-consent.html#92-09", "sub": "9.2 Learning Consent"}, {"t": "s", "c": 9, "ch": "AI-Mediated Interaction", "id": "9.3", "title": "Predictability", "body": "Why stability matters more than surprise.", "url": "9-3-predictability.html"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "93/01", "title": "Design behavior users can reliably anticipate.", "body": "Ensure system actions align with established expectations.", "url": "9-3-predictability.html#93-01", "sub": "9.3 Predictability"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "93/02", "title": "Explain variation across comparable scenarios.", "body": "When similar inputs yield different outputs, show why or show that variation is expected.", "url": "9-3-predictability.html#93-02", "sub": "9.3 Predictability"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "93/03", "title": "Expose stable behavioral patterns, not internal complexity.", "body": "Prioritize outcome clarity over algorithmic explanation.", "url": "9-3-predictability.html#93-03", "sub": "9.3 Predictability"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "93/04", "title": "Constrain and signal system variability.", "body": "Communicate when behavior may differ from prior patterns.", "url": "9-3-predictability.html#93-04", "sub": "9.3 Predictability"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "93/05", "title": "Make output variability explicit.", "body": "Tell users when the same input can yield different results.", "url": "9-3-predictability.html#93-05", "sub": "9.3 Predictability"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "93/06", "title": "Keep variability within stated bounds.", "body": "Do not let outputs vary beyond the range users were led to expect.", "url": "9-3-predictability.html#93-06", "sub": "9.3 Predictability"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "93/07", "title": "Prevent unannounced behavioral drift.", "body": "Communicate meaningful changes to system logic.", "url": "9-3-predictability.html#93-07", "sub": "9.3 Predictability"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "93/08", "title": "Strengthen predictability in automated workflows.", "body": "Increase behavioral transparency as autonomy rises.", "url": "9-3-predictability.html#93-08", "sub": "9.3 Predictability"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "93/09", "title": "Preserve expectation stability during scaling and updates.", "body": "Ensure expansion does not invalidate prior learning.", "url": "9-3-predictability.html#93-09", "sub": "9.3 Predictability"}, {"t": "s", "c": 9, "ch": "AI-Mediated Interaction", "id": "9.4", "title": "Explainability", "body": "How results are understood.", "url": "9-4-explainability.html"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "94/01", "title": "Design explanations to enable informed judgment.", "body": "Ensure explanatory content directly supports user decisions.", "url": "9-4-explainability.html#94-01", "sub": "9.4 Explainability"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "94/02", "title": "Surface causal factors rather than technical mechanisms.", "body": "Explain what influenced the outcome in user-relevant terms.", "url": "9-4-explainability.html#94-02", "sub": "9.4 Explainability"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "94/03", "title": "Explain the individual output.", "body": "Give the reasons for this result in this case, not only a general account of how the model works.", "url": "9-4-explainability.html#94-03", "sub": "9.4 Explainability"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "94/04", "title": "Keep explanations faithful to the model.", "body": "Do not present plausible rationales that did not produce the output.", "url": "9-4-explainability.html#94-04", "sub": "9.4 Explainability"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "94/05", "title": "Show what would change the outcome.", "body": "Indicate which inputs, if different, would have produced a different result.", "url": "9-4-explainability.html#94-05", "sub": "9.4 Explainability"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "94/06", "title": "Repealed", "body": "Repealed—merged into 72/05", "url": "9-4-explainability.html#94-06", "sub": "9.4 Explainability"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "94/07", "title": "Increase transparency as autonomy increases.", "body": "Strengthen explanation mechanisms in automated workflows.", "url": "9-4-explainability.html#94-07", "sub": "9.4 Explainability"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "94/08", "title": "Enable informed disagreement.", "body": "Allow users to challenge outcomes with understanding.", "url": "9-4-explainability.html#94-08", "sub": "9.4 Explainability"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "94/09", "title": "Repealed", "body": "Repealed—merged into 72/06", "url": "9-4-explainability.html#94-09", "sub": "9.4 Explainability"}, {"t": "s", "c": 9, "ch": "AI-Mediated Interaction", "id": "9.5", "title": "Confidence Signaling", "body": "How certainty and uncertainty are conveyed.", "url": "9-5-confidence-signaling.html"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "95/01", "title": "Calibrate confidence to actual reliability.", "body": "Refrain from overstating certainty in system outputs.", "url": "9-5-confidence-signaling.html#95-01", "sub": "9.5 Confidence Signaling"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "95/02", "title": "Surface uncertainty explicitly.", "body": "Ensure absence of signal does not imply correctness.", "url": "9-5-confidence-signaling.html#95-02", "sub": "9.5 Confidence Signaling"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "95/03", "title": "Differentiate uncertainty sources.", "body": "Clarify whether uncertainty arises from missing data, model limits, or ambiguity.", "url": "9-5-confidence-signaling.html#95-03", "sub": "9.5 Confidence Signaling"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "95/04", "title": "Separate presentation fluency from reliability.", "body": "Prevent polished output from implying unwarranted accuracy.", "url": "9-5-confidence-signaling.html#95-04", "sub": "9.5 Confidence Signaling"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "95/05", "title": "Scale confidence signaling to risk level.", "body": "Increase clarity and prominence for high-impact decisions.", "url": "9-5-confidence-signaling.html#95-05", "sub": "9.5 Confidence Signaling"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "95/06", "title": "Tie confidence signals to recommended action.", "body": "Provide guidance when reliability falls below threshold.", "url": "9-5-confidence-signaling.html#95-06", "sub": "9.5 Confidence Signaling"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "95/07", "title": "Maintain stable calibration across updates.", "body": "Safeguard against unexplained shifts in expressed confidence levels.", "url": "9-5-confidence-signaling.html#95-07", "sub": "9.5 Confidence Signaling"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "95/08", "title": "Increase signaling rigor in automated workflows.", "body": "Strengthen transparency when actions are delegated.", "url": "9-5-confidence-signaling.html#95-08", "sub": "9.5 Confidence Signaling"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "95/09", "title": "Ensure clarity under high-pressure conditions.", "body": "Design signals that remain perceivable during urgency.", "url": "9-5-confidence-signaling.html#95-09", "sub": "9.5 Confidence Signaling"}, {"t": "s", "c": 9, "ch": "AI-Mediated Interaction", "id": "9.6", "title": "Graceful Failure", "body": "What happens when intelligence breaks.", "url": "9-6-graceful-failure.html"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "96/01", "title": "Design systems to fail safely by default.", "body": "Assume incorrect outputs will occur and plan containment accordingly.", "url": "9-6-graceful-failure.html#96-01", "sub": "9.6 Graceful Failure"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "96/02", "title": "Contain failure within controlled boundaries.", "body": "Prevent cascading or system-wide consequences.", "url": "9-6-graceful-failure.html#96-02", "sub": "9.6 Graceful Failure"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "96/03", "title": "Implement conservative refusal policies.", "body": "Decline uncertain actions rather than generate unreliable outputs.", "url": "9-6-graceful-failure.html#96-03", "sub": "9.6 Graceful Failure"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "96/04", "title": "Communicate failure transparently.", "body": "Clearly indicate uncertainty, refusal, or degraded performance.", "url": "9-6-graceful-failure.html#96-04", "sub": "9.6 Graceful Failure"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "96/05", "title": "Increase restraint as uncertainty rises.", "body": "Reduce autonomous action under low confidence.", "url": "9-6-graceful-failure.html#96-05", "sub": "9.6 Graceful Failure"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "96/06", "title": "Restrict high-impact capabilities when reliability drops.", "body": "Align action permissions with certainty levels.", "url": "9-6-graceful-failure.html#96-06", "sub": "9.6 Graceful Failure"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "96/07", "title": "Provide explicit, safe fallback paths.", "body": "Activate conservative modes or human oversight when failure conditions arise.", "url": "9-6-graceful-failure.html#96-07", "sub": "9.6 Graceful Failure"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "96/08", "title": "Protect user progress during failure events.", "body": "Ensure data and task continuity remain intact.", "url": "9-6-graceful-failure.html#96-08", "sub": "9.6 Graceful Failure"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "96/09", "title": "Enable structured recovery after failure.", "body": "Support correction, override, or safe continuation.", "url": "9-6-graceful-failure.html#96-09", "sub": "9.6 Graceful Failure"}, {"t": "s", "c": 9, "ch": "AI-Mediated Interaction", "id": "9.7", "title": "Provenance", "body": "What data influenced outcomes.", "url": "9-7-provenance.html"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "97/01", "title": "Trace outcomes to identifiable sources.", "body": "Ensure users can see where information originates.", "url": "9-7-provenance.html#97-01", "sub": "9.7 Provenance"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "97/02", "title": "Make data sources accessible and reviewable.", "body": "Provide inspectable references for inputs and influences.", "url": "9-7-provenance.html#97-02", "sub": "9.7 Provenance"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "97/03", "title": "Attribute composite inputs explicitly.", "body": "Distinguish and label contributions from training data, retrieved sources, and user-supplied input.", "url": "9-7-provenance.html#97-03", "sub": "9.7 Provenance"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "97/04", "title": "Maintain traceability through transformations.", "body": "Ensure derived outputs link back to original data.", "url": "9-7-provenance.html#97-04", "sub": "9.7 Provenance"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "97/05", "title": "Surface contextual suitability of sources.", "body": "Indicate when data may not apply to the current situation.", "url": "9-7-provenance.html#97-05", "sub": "9.7 Provenance"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "97/06", "title": "Display data recency clearly.", "body": "Communicate timestamps and update cycles for inputs.", "url": "9-7-provenance.html#97-06", "sub": "9.7 Provenance"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "97/07", "title": "Signal incomplete or uncertain origins.", "body": "Highlight missing attribution or ambiguous sourcing.", "url": "9-7-provenance.html#97-07", "sub": "9.7 Provenance"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "97/08", "title": "Increase provenance rigor in automated systems.", "body": "Strengthen traceability as automation scales.", "url": "9-7-provenance.html#97-08", "sub": "9.7 Provenance"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "97/09", "title": "Enable challenge through traceability.", "body": "Design systems so users can question and verify inputs.", "url": "9-7-provenance.html#97-09", "sub": "9.7 Provenance"}, {"t": "s", "c": 9, "ch": "AI-Mediated Interaction", "id": "9.8", "title": "Bias Management", "body": "Where distortions may arise.", "url": "9-8-bias-management.html"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "98/01", "title": "Treat bias as a systemic risk.", "body": "Design structural safeguards rather than ad hoc corrections.", "url": "9-8-bias-management.html#98-01", "sub": "9.8 Bias Management"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "98/02", "title": "Integrate bias prevention into design.", "body": "Assess and mitigate bias risks before deployment.", "url": "9-8-bias-management.html#98-02", "sub": "9.8 Bias Management"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "98/03", "title": "Instrument systems to detect bias proactively.", "body": "Measure fairness rather than assuming neutrality.", "url": "9-8-bias-management.html#98-03", "sub": "9.8 Bias Management"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "98/04", "title": "Evaluate bias by outcome impact.", "body": "Prioritize measurable effects over stated intentions.", "url": "9-8-bias-management.html#98-04", "sub": "9.8 Bias Management"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "98/05", "title": "Calibrate bias safeguards to domain risk.", "body": "Increase rigor in high-consequence environments.", "url": "9-8-bias-management.html#98-05", "sub": "9.8 Bias Management"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "98/06", "title": "Surface fairness indicators where relevant.", "body": "Make potential bias risks perceptible to users.", "url": "9-8-bias-management.html#98-06", "sub": "9.8 Bias Management"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "98/07", "title": "Provide actionable mitigation pathways.", "body": "Enable reporting, correction, or override when bias is detected.", "url": "9-8-bias-management.html#98-07", "sub": "9.8 Bias Management"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "98/08", "title": "Escalate to human review in sensitive contexts.", "body": "Limit autonomous decisions where fairness risks are high.", "url": "9-8-bias-management.html#98-08", "sub": "9.8 Bias Management"}, {"t": "s", "c": 9, "ch": "AI-Mediated Interaction", "id": "9.9", "title": "Trust Calibration", "body": "How reliance is adjusted over time.", "url": "9-9-trust-calibration.html"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "99/01", "title": "Align user reliance with actual system reliability.", "body": "Design mechanisms that prevent both overreliance and avoidance.", "url": "9-9-trust-calibration.html#99-01", "sub": "9.9 Trust Calibration"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "99/02", "title": "Keep trust signals current with measured performance.", "body": "Update defaults, messaging, and permissions as measured reliability changes over time.", "url": "9-9-trust-calibration.html#99-02", "sub": "9.9 Trust Calibration"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "99/03", "title": "Calibrate trust contextually.", "body": "Adjust signaling and controls according to task and risk domain.", "url": "9-9-trust-calibration.html#99-03", "sub": "9.9 Trust Calibration"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "99/04", "title": "Reinforce trust through consistent outcomes.", "body": "Prioritize experiential reliability over declarative assurance.", "url": "9-9-trust-calibration.html#99-04", "sub": "9.9 Trust Calibration"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "99/05", "title": "Track reliance in delegated workflows.", "body": "Monitor whether users over- or under-rely on delegated actions and adjust oversight accordingly.", "url": "9-9-trust-calibration.html#99-05", "sub": "9.9 Trust Calibration"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "99/06", "title": "Continuously reassess trust alignment.", "body": "Monitor and adjust reliance mechanisms over time.", "url": "9-9-trust-calibration.html#99-06", "sub": "9.9 Trust Calibration"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "99/07", "title": "Signal reliability improvements transparently.", "body": "Increase permitted reliance only when performance demonstrably improves.", "url": "9-9-trust-calibration.html#99-07", "sub": "9.9 Trust Calibration"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "99/08", "title": "Reduce trust signals when performance declines.", "body": "Promptly adjust confidence and permissions in response to degradation.", "url": "9-9-trust-calibration.html#99-08", "sub": "9.9 Trust Calibration"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "99/09", "title": "Provide immediate feedback to correct miscalibration.", "body": "Address overtrust or undertrust before patterns solidify.", "url": "9-9-trust-calibration.html#99-09", "sub": "9.9 Trust Calibration"}, {"t": "s", "c": 9, "ch": "AI-Mediated Interaction", "id": "9.10", "title": "Non-Anthropomorphism", "body": "How to prevent false human attribution.", "url": "9-10-non-anthropomorphism.html"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "910/01", "title": "Design to prevent false human attribution.", "body": "Actively discourage mental models that treat the system as a person.", "url": "9-10-non-anthropomorphism.html#910-01", "sub": "9.10 Non-Anthropomorphism"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "910/02", "title": "Prevent cues that imply human emotion or intent.", "body": "Do not simulate empathy or consciousness to increase engagement.", "url": "9-10-non-anthropomorphism.html#910-02", "sub": "9.10 Non-Anthropomorphism"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "910/03", "title": "Use language that reflects functional capability.", "body": "Avoid phrasing that implies awareness, desire, or understanding.", "url": "9-10-non-anthropomorphism.html#910-03", "sub": "9.10 Non-Anthropomorphism"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "910/04", "title": "Represent system agency truthfully.", "body": "Frame outputs as computational processes, not deliberate actions.", "url": "9-10-non-anthropomorphism.html#910-04", "sub": "9.10 Non-Anthropomorphism"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "910/05", "title": "Make system limitations explicit.", "body": "Clearly communicate constraints, uncertainties, and boundaries.", "url": "9-10-non-anthropomorphism.html#910-05", "sub": "9.10 Non-Anthropomorphism"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "910/06", "title": "Preserve human accountability in system framing.", "body": "Ensure responsibility is not shifted to the system persona.", "url": "9-10-non-anthropomorphism.html#910-06", "sub": "9.10 Non-Anthropomorphism"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "910/07", "title": "Prefer functional metaphors over social metaphors.", "body": "Refrain from metaphors that imply thought, belief, or motive.", "url": "9-10-non-anthropomorphism.html#910-07", "sub": "9.10 Non-Anthropomorphism"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "910/08", "title": "Separate fluency from epistemic authority.", "body": "Prevent polished interaction from implying comprehension.", "url": "9-10-non-anthropomorphism.html#910-08", "sub": "9.10 Non-Anthropomorphism"}, {"t": "d", "c": 9, "ch": "AI-Mediated Interaction", "id": "910/09", "title": "Limit human-like interaction patterns in high-risk contexts.", "body": "Reduce social signaling where overtrust would be harmful.", "url": "9-10-non-anthropomorphism.html#910-09", "sub": "9.10 Non-Anthropomorphism"}];
